async function loadState() {
  try { const r = await window.storage.get(STORE_KEY); return r ? JSON.parse(r.value) : null; } catch { return null; }
}
async function saveState(s) { try { await window.storage.set(STORE_KEY, JSON.stringify(s)); } catch {} }
function todayStr() { return new Date().toISOString().slice(0, 10); }
function domName(id, lang) { return lang === "en" ? DOM_NAME_EN[id] : DOM_NAME[id]; }
// 問題テキストを言語に応じて取り出す（英語フィールドが無ければ日本語にフォールバック）
function qText(Q, lang) { return lang === "en" && Q.qEn ? Q.qEn : Q.q; }
function qOpts(Q, lang) { return lang === "en" && Q.oEn ? Q.oEn : Q.o; }
function qExpl(Q, lang) { return lang === "en" && Q.eEn ? Q.eEn : Q.e; }
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}
function arrEq(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b)) return false;
  if (a.length !== b.length) return false;
  const sa = [...a].sort(), sb = [...b].sort();
  return sa.every((v, i) => v === sb[i]);
}

function App() {
  const [tab, _setTab] = useState("home");
  const [tabHist, setTabHist] = useState([]);
  const backRef = useRef(null);
  const setTab = (k) => { if (k !== tab) setTabHist(h => [...h, tab]); _setTab(k); };
  const goBackTab = () => { if (backRef.current && backRef.current()) { if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); return; } if (!tabHist.length) return; const prev = tabHist[tabHist.length - 1]; setTabHist(tabHist.slice(0, -1)); _setTab(prev); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); };
  const [state, setState] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const [lang, setLang] = useState(certInitLang);
  const t = T[lang];

  useEffect(() => {
    loadState().then(s => {
      const init = s || { progress: {}, meta: { streak: 0, lastDay: "", dailyDay: "", dailyCount: 0 }, review: [] };
      if (!init.review) init.review = [];
      setState(init);
      setLoaded(true);
    });
  }, []);

  const persist = (next) => { setState(next); saveState(next); };

  // 弱点問題（間違えた問題）を蓄積／解消する
  const addReview = (q) => {
    setState(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      if (!next.review) next.review = [];
      const key = q.q;
      if (!next.review.some(r => r.q === key)) {
        next.review.push({ d: q.d, q: q.q, o: q.o, a: q.a, e: q.e, multi: !!q.multi });
      }
      saveState(next);
      return next;
    });
  };
  const removeReview = (qText) => {
    setState(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      next.review = (next.review || []).filter(r => r.q !== qText);
      saveState(next);
      return next;
    });
  };
  const clearReview = () => {
    setState(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      next.review = [];
      saveState(next);
      return next;
    });
  };

  const record = (domId, correct) => { try { novaLogStudy(); } catch (e) {}
    setState(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      if (!next.progress[domId]) next.progress[domId] = { correct: 0, attempts: 0 };
      next.progress[domId].attempts++;
      if (correct) next.progress[domId].correct++;
      const today = todayStr();
      if (next.meta.dailyDay !== today) { next.meta.dailyDay = today; next.meta.dailyCount = 0; }
      next.meta.dailyCount++;
      if (next.meta.lastDay !== today) {
        const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
        next.meta.streak = next.meta.lastDay === yesterday ? next.meta.streak + 1 : 1;
        next.meta.lastDay = today;
      }
      saveState(next);
      return next;
    });
  };

  if (!loaded) return <div style={{ padding: 40, textAlign: "center", color: C.deep }}>{t.loading}</div>;

  const reviewCount = (state.review || []).length;
  const TABS = [
    ["home", t.tabHome], ["quiz", t.tabQuiz], ["exam", t.tabExam],
    ["review", reviewCount > 0 ? `${t.tabReview} (${reviewCount})` : t.tabReview],
    ["diagram", t.tabDiagram], ["compare", t.tabCompare], ["confuse", t.tabConfuse], ["glossary", t.tabGlossary],
  ];

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: C.ink, background: "#FFFDF9", minHeight: "100vh" }}>
      <div style={{ background: C.deep, color: nvInk("#ffffff", C.deep), padding: "16px 18px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <div style={{ fontSize: 19, fontWeight: 700 }}>
            <span style={{ color: C.primary }}>aws</span> {t.appTitle}
          </div>
          <div style={{ fontSize: 12, marginTop: 2 }}>{t.appSub}</div>
        </div>
        <div style={{ display: "flex", background: "rgba(255,255,255,.15)", borderRadius: 20, padding: 3 }}>
          {["ja", "en"].map(l => (
            <button key={l} onClick={() => setLang(l)}
              style={{ border: "none", cursor: "pointer", borderRadius: 16, padding: "5px 12px", fontSize: 12, fontWeight: 700,
                background: lang === l ? "#fff" : "transparent", color: lang === l ? nvInk(C.deep, "#ffffff") : "#fff" }}>
              {l === "ja" ? "日本語" : "English"}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", borderBottom: `2px solid ${C.mid}`, background: C.light }}>
        {TABS.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)}
            style={{ flex: "1 1 auto", padding: "11px 8px", border: "none", cursor: "pointer",
              background: tab === k ? "#fff" : "transparent", color: tab === k ? nvInk(C.deep, "#ffffff") : C.ink,
              fontWeight: tab === k ? 700 : 500, fontSize: 13, borderBottom: tab === k ? `3px solid ${C.primary}` : "3px solid transparent" }}>
            {label}
          </button>
        ))}
      </div>
      {tabHist.length > 0 && (
        <button onClick={goBackTab}
          aria-label="Back"
          style={{ position: "fixed", right: 16, bottom: 104, zIndex: 45, border: `1.5px solid ${C.deep}`, cursor: "pointer", borderRadius: 22, padding: "9px 15px", background: "#fff", color: C.deep, fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.20)" }}>
          ← {lang === "en" ? "Back" : "戻る"}
        </button>
      )}
      {tab !== "home" && (
        <button onClick={() => { setTab("home"); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); }}
          aria-label="Back to top"
          style={{ position: "fixed", right: 16, bottom: 60, zIndex: 45, border: "none", cursor: "pointer", borderRadius: 22, padding: "10px 15px", background: C.deep, color: nvInk("#ffffff", C.deep), fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.28)" }}>
          ↑ {lang === "en" ? "Top" : "トップへ"}
        </button>
      )}
      <div style={{ padding: 16, maxWidth: 820, margin: "0 auto" }}>
        {tab === "home" && <Home state={state} lang={lang} t={t} />}
        {tab === "quiz" && <Quiz onAnswer={record} lang={lang} t={t} />}
        {tab === "exam" && <MSExamShell sets={EXAM_SETS} setKeys={[1, 2, 3, 4, 5]} domainSets={SAA_DOMAIN_SETS} domains={DOMAINS} lang={lang} C={C} PASS={PASS} onAnswer={record} onWrong={addReview} examId="saa" saveKey="saa_c03_study_v1:msexam_resume" />}
        {tab === "review" && <Review state={state} onAnswer={record} onResolve={removeReview} onClear={clearReview} lang={lang} t={t} />}
        {tab === "diagram" && <Diagrams lang={lang} t={t} />}
        {tab === "compare" && <Compare lang={lang} t={t} />}
        {tab === "confuse" && <Confuse lang={lang} t={t} />}
        {tab === "glossary" && <Glossary lang={lang} t={t} />}
      </div>
    </div>
  );
}

function Home({ state, lang, t }) {
  const totals = useMemo(() => {
    let c = 0, a = 0;
    Object.values(state.progress).forEach(p => { c += p.correct; a += p.attempts; });
    return { c, a, rate: a ? Math.round((c / a) * 100) : 0 };
  }, [state]);
  const weak = useMemo(() => DOMAINS.map(d => {
    const p = state.progress[d.id] || { correct: 0, attempts: 0 };
    const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : null;
    return { ...d, rate, attempts: p.attempts };
  }).filter(d => d.attempts > 0).sort((a, b) => a.rate - b.rate), [state]);
  const dailyPct = Math.min(100, Math.round((state.meta.dailyCount / DAILY_GOAL) * 100));
  return (
    <div>
      <div style={{ marginBottom: 16 }}>
        <Stat label={t.overallRate} value={`${totals.rate}%`} sub={`${totals.c}/${totals.a}${t.questionsUnit}`} color={totals.rate >= PASS ? C.ok : C.primary} />
      </div>
      <Card title={`${t.dailyGoal} (${state.meta.dailyCount}/${DAILY_GOAL})`}>
        <Bar pct={dailyPct} color={dailyPct >= 100 ? C.ok : C.primary} />
        <div style={{ fontSize: 12, marginTop: 6, color: "#6b5d52" }}>{dailyPct >= 100 ? t.dailyDone : t.dailyRemain(DAILY_GOAL - state.meta.dailyCount)}</div>
      </Card>
      <Card title={t.domMastery}>
        {DOMAINS.map(d => {
          const p = state.progress[d.id] || { correct: 0, attempts: 0 };
          const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : 0;
          return (
            <div key={d.id} style={{ marginBottom: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span style={{ fontWeight: 600 }}>
                  <span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
                  {domName(d.id, lang)}
                </span>
                <span style={{ color: "#6b5d52" }}>{d.pct}% · {p.attempts ? `${rate}%` : t.notStarted}</span>
              </div>
              <Bar pct={rate} color={d.hue} faint={!p.attempts} />
            </div>
          );
        })}
      </Card>
      {weak.length > 0 && (
        <Card title={t.weakDomains}>
          {weak.slice(0, 3).map(d => (
            <div key={d.id} style={{ fontSize: 13, padding: "6px 0", borderBottom: `1px solid ${C.light}` }}>
              <span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
              {domName(d.id, lang)} — <strong style={{ color: d.rate < PASS ? C.ng : C.ok }}>{d.rate}%</strong>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}

function Stat({ label, value, sub, color }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14 }}>
      <div style={{ fontSize: 11.5, color: "#6b5d52" }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 800, color: color ? nvInk(color, "#ffffff", 3) : undefined }}>{value}</div>
      <div style={{ fontSize: 11, color: "#7b6d62" }}>{sub}</div>
    </div>
  );
}
function Card({ title, children }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep, marginBottom: 10 }}>{title}</div>
      {children}
    </div>
  );
}
function Bar({ pct, color, faint }) {
  return (
    <div style={{ background: C.light, borderRadius: 8, height: 9, overflow: "hidden" }}>
      <div style={{ width: `${pct}%`, height: "100%", background: faint ? C.mid : color, transition: "width .3s" }} />
    </div>
  );
}

function Quiz({ onAnswer, lang, t }) {
  const en = lang === "en";
  const [filter, setFilter] = useState("ALL");
  const [shuf, setShuf] = useState(false);
  const [pos, setPos] = useState(0);
  const [sel, setSel] = useState(null);
  const [seed, setSeed] = useState(0);
  const slot = useQuizSlot("saa_c03_study_v1:quiz_resume");
  const domDone = useDoneSet("saa_c03_study_v1:quiz_resume:dc");
  const resumeRef = useRef(null);
  const pool = useMemo(() => {
    const idxs = filter === "ALL" ? BANK.map((_, i) => i) : BANK.map((_, i) => i).filter(i => BANK[i].d === filter);
    return shuf ? shuffle(idxs) : idxs;
  }, [filter, shuf, seed]);
  useEffect(() => { if (resumeRef.current) { const r = resumeRef.current; resumeRef.current = null; setPos(r.pos || 0); setSel(null); return; } setPos(0); setSel(null); }, [pool]);
  if (pool.length === 0) return null;
  const qi = pool[Math.min(pos, pool.length - 1)];
  const Q = BANK[qi];
  const choose = (i) => { if (sel !== null) return; setSel(i); onAnswer(Q.d, i === Q.a); };
  const go = (d) => { setSel(null); setPos(p => Math.max(0, Math.min(pool.length - 1, p + d))); };
  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
        <button onClick={() => slot.save({ filter, shuf, seed, pos }, filter === "ALL" ? (en ? "All" : "全分野") : filter)} style={{ padding: "6px 14px", borderRadius: 8, border: `1.5px solid ${C.primary}`, background: "#fff", color: nvInk(C.primary, "#ffffff"), fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>{slot.meta ? (en ? "💾 Saved" : "💾 保存済") : (en ? "💾 Save" : "💾 セーブ")}</button>
        {slot.meta && (<>
          <button onClick={async () => { const d = await slot.read(); if (!d) return; resumeRef.current = { pos: d.pos || 0 }; setFilter(d.filter || "ALL"); setShuf(!!d.shuf); setSeed(d.seed || 0); setPos(d.pos || 0); setSel(null); }} style={{ padding: "6px 14px", borderRadius: 8, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary), fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>{en ? "▶ Resume" : "▶ 続きから"}</button>
          <span style={{ fontSize: 11, color: "#5a7288" }}>{saveStamp(slot.meta.t)}</span>
          <button onClick={() => slot.remove()} style={{ marginLeft: "auto", padding: "6px 10px", borderRadius: 8, border: "1px solid #cbd5e1", background: "#fff", color: "#7d93a8", fontSize: 11, cursor: "pointer" }}>{en ? "Delete" : "削除"}</button>
        </>)}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
        <div style={{ fontSize: 13, color: "#7b6d62", fontWeight: 600 }}>{en ? `${pool.length} questions` : `全${pool.length}問`}</div>
        <div style={{ display: "inline-flex", background: C.light, borderRadius: 20, padding: 3 }}>
          {[[false, en ? "Fixed order" : "固定順"], [true, en ? "Random" : "ランダム"]].map(([val, label]) => (
            <button key={String(val)} onClick={() => { setShuf(val); setSeed(x => x + 1); }}
              style={{ border: "none", cursor: "pointer", borderRadius: 16, padding: "6px 16px", fontSize: 12.5, fontWeight: 700,
                background: shuf === val ? "#fff" : "transparent", color: shuf === val ? nvInk(C.deep, "#ffffff") : nvInk("#7b6d62", C.mid),
                boxShadow: shuf === val ? "0 1px 3px rgba(0,0,0,.12)" : "none" }}>
              {label}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
        {["ALL", ...DOMAINS.map(d => d.id)].map(k => (
          <button key={k} onClick={() => setFilter(k)}
            style={{ display: "inline-flex", alignItems: "center", padding: "6px 14px", borderRadius: 18, fontSize: 13, cursor: "pointer",
              border: `1.5px solid ${filter === k ? C.primary : C.mid}`, background: filter === k ? C.primary : "#fff", color: filter === k ? C.deep : nvInk(C.ink, "#ffffff"), fontWeight: 700 }}><DoneCheck on={domDone.has(k)} onToggle={(e) => domDone.toggle(k, e)} /><span>{k === "ALL" ? t.allFields : k}</span></button>
        ))}
      </div>
      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 18 }}>
        <div style={{ fontSize: 11.5, color: nvInk("#ffffff", DOM_HUE[Q.d]), background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 5, padding: "3px 10px", marginBottom: 14 }}>{Q.d} · {domName(Q.d, lang)}</div>
        <div style={{ fontSize: 16, fontWeight: 700, marginBottom: 16, lineHeight: 1.5, display: "flex", alignItems: "flex-start", gap: 6 }}><span style={{ flex: 1 }}>{qText(Q, lang)}</span><StarButton id={"q#" + novaQHash(Q.q || Q.j || Q.qEn || "")} text={qText(Q, lang)} scope={lang === "en" ? "Quiz" : "クイズ"} /></div>
        {qOpts(Q, lang).map((opt, i) => {
          let bg = "#fff", bd = C.mid, col = C.ink;
          if (sel !== null) {
            if (i === Q.a) { bg = "#E8F5EE"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; }
          }
          return (
            <button key={i} onClick={() => choose(i)} disabled={sel !== null}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 10, padding: "14px 16px", borderRadius: 10,
                border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel === null ? "pointer" : "default",
                fontSize: 14, lineHeight: 1.4, fontWeight: sel !== null && i === Q.a ? 700 : 500 }}>
              <span style={{ fontWeight: 700, marginRight: 10 }}>{sel !== null && (i === Q.a) ? "✓" : sel !== null && (i === sel) ? "✗" : "ABCD"[i]}</span>{opt}
              {sel !== null && Q.oe && Q.oe[i] ? <div style={{ marginTop: 6, marginLeft: 26, fontSize: 12, lineHeight: 1.5, fontWeight: 500, color: i === Q.a ? C.ok : (i === sel ? C.ng : "#8a94a6") }}>{(i === Q.a ? "◎ " : "✗ ") + Q.oe[i]}</div> : null}
            </button>
          );
        })}
        {sel !== null && (
          <div style={{ marginTop: 12 }}>
            <div style={{ background: C.light, borderRadius: 9, padding: 13, fontSize: 13.5, lineHeight: 1.55 }}>
              <strong style={{ color: nvInk(sel === Q.a ? C.ok : C.ng, C.light) }}>{sel === Q.a ? t.correct : t.incorrect}</strong>・{t.answerIs("ABCD"[Q.a])}{qExpl(Q, lang)}
            </div>
            {Q.ref ? <div style={{ marginTop: 8, fontSize: 11.5, color: "#8a94a6", lineHeight: 1.5 }}>{Q.ref}</div> : null}
            {pos + 1 < pool.length && (
              <button onClick={() => go(1)} style={{ marginTop: 12, width: "100%", padding: 13, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{t.nextQ}</button>
            )}
          </div>
        )}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 14 }}>
        <button onClick={() => go(-1)} disabled={pos === 0}
          style={{ padding: "10px 30px", borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: pos === 0 ? nvInk("#bcae9f", "#ffffff", 3) : C.ink, fontWeight: 700, fontSize: 13.5, cursor: pos === 0 ? "default" : "pointer" }}>
          ← {en ? "Prev" : "前の問題"}
        </button>
        <span style={{ fontSize: 13.5, color: "#7b6d62", fontWeight: 600 }}>{pos + 1} / {pool.length}</span>
        <button onClick={() => go(1)} style={{ padding: "10px 30px", borderRadius: 9, fontSize: 13.5, fontWeight: 700, border: `1.5px solid ${C.primary}`, background: "#fff", color: nvInk(C.primary, "#ffffff"), cursor: "pointer" }}>{t.nextQ}</button>
      </div>
    </div>
  );
}

function Compare({ lang, t }) {
  const norm = (COMPARE_TABLES || []).map((tb) => ({
    title: tb.title, titleEn: tb.titleEn,
    axisJa: (tb.headers || [])[0], axisEn: ((tb.headersEn || tb.headers) || [])[0],
    cols: (tb.headers || []).slice(1), colsEn: ((tb.headersEn || tb.headers) || []).slice(1),
    rows: tb.rows, rowsEn: tb.rowsEn || tb.rows,
  }));
  return (
    <div>
      {t.compareIntro ? <div style={{ fontSize: 12, color: "#7b6d62", marginBottom: 10 }}>{t.compareIntro}</div> : null}
      <CmpTable compare={norm} C={C} lang={lang} t={t} />
    </div>
  );
}

function Confuse({ lang, t }) {
  const [q, setQ] = useState("");
  const list = CONFUSE.filter(c => !q || c.join("").toLowerCase().includes(q.toLowerCase()));
  return (
    <div>
      <input value={q} onChange={e => setQ(e.target.value)} aria-label={t.confuseSearch} placeholder={t.confuseSearch}
        style={{ width: "100%", padding: 11, borderRadius: 9, border: `1.5px solid ${C.mid}`, fontSize: 14, marginBottom: 14, boxSizing: "border-box" }} />
      {list.map((c, i) => (
        <div key={i} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 10, padding: 13, marginBottom: 10 }}>
          <div style={{ fontWeight: 700, color: C.deep, fontSize: 13.5, marginBottom: 5 }}>{lang === "en" && c[3] ? c[3] : c[0]}</div>
          <div style={{ fontSize: 13, lineHeight: 1.5, marginBottom: 4 }}>{lang === "en" && c[4] ? c[4] : c[1]}</div>
          <div style={{ fontSize: 12, color: nvInk(C.primary, "#ffffff"), fontWeight: 600 }}>{t.judgeAxis}：{lang === "en" && c[5] ? c[5] : c[2]}</div>
        </div>
      ))}
      {list.length === 0 && <div style={{ textAlign: "center", color: "#7b6d62", padding: 20 }}>{t.noMatch}</div>}
    </div>
  );
}

function Glossary({ lang, t }) {
  return <GlossaryView GLOSSARY={GLOSSARY} GLOSSARY_CATS={GLOSSARY_CATS} DOM_HUE={DOM_HUE} C={C} lang={lang} t={t} />;
}

function Review({ state, onAnswer, onResolve, onClear, lang, t }) {
  const en = lang === "en";
  const list = state.review || [];
  const [phase, setPhase] = useState("list"); // list | quiz
  const [pos, setPos] = useState(0);
  const [pick, setPick] = useState([]);
  const [revealed, setRevealed] = useState(false);

  if (list.length === 0) {
    return (
      <Card title={t.reviewTitle}>
        <div style={{ fontSize: 13, color: "#6b5d52", lineHeight: 1.6 }}>{t.reviewEmpty}</div>
      </Card>
    );
  }

  if (phase === "list") {
    return (
      <div>
        <Card title={t.reviewTitle}>
          <div style={{ fontSize: 13, color: "#5a4d43", lineHeight: 1.6, marginBottom: 12 }}>{t.reviewIntro(list.length)}</div>
          <button onClick={() => { setPhase("quiz"); setPos(0); setPick([]); setRevealed(false); }}
            style={{ width: "100%", padding: 13, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer", marginBottom: 8 }}>
            {t.reviewStart}
          </button>
          <button onClick={onClear} style={{ width: "100%", padding: 10, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ng, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{t.reviewClear}</button>
        </Card>
        {list.map((q, i) => (
          <div key={i} style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 10, padding: 12, marginBottom: 9 }}>
            <div style={{ fontSize: 13, fontWeight: 600, lineHeight: 1.5 }}>
              <span style={{ background: DOM_HUE[q.d], color: nvInk("#ffffff", DOM_HUE[q.d]), borderRadius: 4, padding: "1px 6px", fontSize: 10.5, marginRight: 6 }}>{q.d}</span>{q.q}
            </div>
          </div>
        ))}
      </div>
    );
  }

  // quiz
  const safePos = Math.min(pos, list.length - 1);
  const Q = list[safePos];
  if (!Q) {
    return (
      <Card title={t.reviewTitle}>
        <div style={{ fontSize: 14, color: C.ok, fontWeight: 700, textAlign: "center", padding: 10 }}>{t.reviewAllDone}</div>
        <button onClick={() => setPhase("list")} style={{ width: "100%", marginTop: 10, padding: 12, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.reviewBackList}</button>
      </Card>
    );
  }
  const multi = !!Q.multi;
  const numNeeded = Array.isArray(Q.a) ? Q.a.length : 1;
  const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
  const isCorrect = arrEq(pick, correctAns);

  const toggle = (i) => {
    if (revealed) return;
    if (multi) setPick(p => p.includes(i) ? p.filter(x => x !== i) : [...p, i]);
    else setPick([i]);
  };
  const check = () => {
    setRevealed(true);
    onAnswer(Q.d, isCorrect);
    if (isCorrect) onResolve(Q.q);
  };
  const next = () => {
    // 正解で消えた場合は同じ index に次の問題が来る。不正解なら次へ。
    const nextPos = isCorrect ? safePos : safePos + 1;
    setPos(nextPos);
    setPick([]);
    setRevealed(false);
  };
  const remaining = list.length;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, background: C.deep, color: nvInk("#ffffff", C.deep), borderRadius: 9, padding: "9px 14px" }}>
        <span style={{ fontSize: 13, fontWeight: 700 }}>{t.reviewTitle}</span>
        <span style={{ fontSize: 13, fontWeight: 700 }}>{en ? "Remaining" : "残り"}: {remaining}</span>
      </div>
      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11, color: nvInk("#ffffff", DOM_HUE[Q.d]), background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>{Q.d} · {domName(Q.d, lang)}</div>
        {multi && <div style={{ display: "inline-block", marginLeft: 8, fontSize: 11, color: C.accent, fontWeight: 700, border: `1px solid ${C.accent}`, borderRadius: 4, padding: "2px 8px" }}>{t.multiSelect(numNeeded)}</div>}
        <div style={{ fontSize: 15, fontWeight: 600, margin: "12px 0 14px", lineHeight: 1.6 }}>{qText(Q, lang)}</div>
        {qOpts(Q, lang).map((opt, i) => {
          const on = pick.includes(i);
          let bg = on ? C.light : "#fff", bd = on ? C.primary : C.mid, col = C.ink, fw = on ? 700 : 500;
          let mark = on ? "✓" : "ABCD"[i], markBg = on ? C.primary : "#fff", markBd = on ? C.primary : C.mid;
          if (revealed) {
            if (correctAns.includes(i)) { bg = "#E8F5EE"; bd = C.ok; col = C.ok; fw = 700; markBg = C.ok; markBd = C.ok; mark = "✓"; }
            else if (on) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; fw = 700; markBg = C.ng; markBd = C.ng; mark = "✕"; }
            else { mark = "ABCD"[i]; markBg = "#fff"; markBd = C.mid; }
          }
          return (
            <button key={i} onClick={() => toggle(i)} disabled={revealed}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9,
                border: `1.5px solid ${bd}`, background: bg, color: col, cursor: revealed ? "default" : "pointer", fontSize: 13.5, lineHeight: 1.45, fontWeight: fw }}>
              <span style={{ display: "inline-block", minWidth: 20, height: 20, lineHeight: "18px", textAlign: "center", marginRight: 8, borderRadius: multi ? 4 : 10, border: `2px solid ${markBd}`, background: markBg, color: markBg === "#fff" ? C.deep : "#fff", fontSize: 11, fontWeight: 700 }}>{mark}</span>{opt}
            </button>
          );
        })}
        {revealed && (
          <div style={{ marginTop: 12, background: C.light, borderRadius: 9, padding: 13, fontSize: 13.5, lineHeight: 1.55 }}>
            <strong style={{ color: nvInk(isCorrect ? C.ok : C.ng, C.light) }}>{isCorrect ? t.correct : t.incorrect}</strong>・{t.answerIs(correctAns.map(x => "ABCD"[x]).join(", "))}{qExpl(Q, lang)}
            {isCorrect && <div style={{ color: C.ok, fontWeight: 700, marginTop: 6 }}>✓ {t.reviewMastered}</div>}
          </div>
        )}
      </div>
      <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
        <button onClick={() => setPhase("list")} style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ink, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.reviewBackList}</button>
        {!revealed ? (
          <button onClick={check} disabled={pick.length === 0} style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: pick.length === 0 ? C.mid : C.accent, color: nvInk("#ffffff", pick.length === 0 ? C.mid : C.accent, 3), fontWeight: 700, fontSize: 14, cursor: pick.length === 0 ? "default" : "pointer" }}>{t.showAnswer}</button>
        ) : (
          <button onClick={next} style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.checkContinue}</button>
        )}
      </div>
    </div>
  );
}

const SAA_EXAM_CASES = [{"id":"saa-1","title":{"ja":"生鮮即日配達SaaS「スイフトカート」の可用性・スケール・コスト最適化設計","en":"Availability, Scale, and Cost Optimization Design for the Grocery Same-Day Delivery SaaS \"SwiftCart\""},"body":{"ja":["株式会社スイフトカートは、都市部向けに生鮮食品の即日配達を提供するEC/SaaS企業である。過去18か月で登録ユーザーは12万人から95万人へ急増し、加盟店舗数も420店から2,600店へ拡大した。サービスは東京リージョン（ap-northeast-1）の単一VPC上で稼働しており、注文受付・在庫参照・配達追跡・販促メディア配信を1つのモノリシックなWebアプリで担っている。経営層は次の資金調達に向け、可用性とコストの両立を強く求めている。","現行アーキテクチャは、パブリックサブネットに配置した2台のEC2（同一アベイラビリティゾーンのm5.xlarge）でWeb/APIを処理し、その前段にElastic IPを1つ割り当てている。データストアは同じくパブリックサブネット寄りに置かれた単一AZのRDS for PostgreSQL（db.r5.large）で、注文・在庫・会員情報をすべて保持する。商品画像や販促動画などの静的コンテンツはEC2のローカルディスクから直接配信しており、キャンペーン時に配信帯域が逼迫する。バックアップは日次のRDS自動スナップショットのみで、アプリ層の構成はマニュアルで再構築している。","トラフィックは強い時間帯集中を示す。平日の18時〜21時に注文が集中し、給料日直後やタイムセール開始時には平常時の8〜11倍のリクエストが数分で押し寄せる。この瞬間的スパイク時に、同期的な在庫確定・決済処理がWeb層を飽和させ、タイムアウトと二重注文が発生している。一方で深夜帯（2時〜6時）はほぼアイドルであり、常時2台構成は閑散時間帯に無駄なコストを生んでいる。","非機能要件として、注文APIの可用性は月間99.95%以上、主要ページのP95応答時間は300ミリ秒以内、決済関連データのRPOは5分以内、リージョン障害時のRTOは4時間以内が求められている。加えて、会員の個人情報と決済トークンを保持するデータストアはインターネットから直接到達不可能なネットワークに隔離し、暗号鍵を組織で管理することがセキュリティ監査の指摘事項として挙がっている。年間のインフラ予算は据え置きのまま、トラフィック3倍成長を吸収することが条件である。","現在の主な課題は4点に集約される。第一に、単一AZ・単一EIP・手動復旧のWeb層とDB層が明確な単一障害点となっている。第二に、スパイク時の同期処理がボトルネックとなり注文取りこぼしが発生する。第三に、静的コンテンツのオリジン配信がEC2のCPUと帯域を圧迫し、応答時間目標を脅かす。第四に、リージョン障害に対する復旧手段が事実上存在せず、RTO/RPO要件を満たせない。"],"en":["SwiftCart, Inc. is an e-commerce/SaaS company offering same-day delivery of fresh groceries to urban areas. Over the past 18 months, registered users surged from 120,000 to 950,000, and partner stores grew from 420 to 2,600. The service runs in a single VPC in the Tokyo Region (ap-northeast-1), where a single monolithic web application handles order intake, inventory lookup, delivery tracking, and promotional media delivery. Ahead of its next funding round, leadership strongly demands both high availability and cost control.","The current architecture processes web/API traffic on two EC2 instances (m5.xlarge in the same Availability Zone) in a public subnet, fronted by a single Elastic IP. The data store is a single-AZ RDS for PostgreSQL (db.r5.large) placed near the public subnet, holding all order, inventory, and member data. Static content such as product images and promotional videos is served directly from the EC2 local disk, and delivery bandwidth becomes saturated during campaigns. Backups consist only of daily automated RDS snapshots, and the application tier is rebuilt manually.","Traffic shows strong time-of-day concentration. Orders concentrate between 18:00 and 21:00 on weekdays, and just after payday or at the start of flash sales, requests reach 8 to 11 times the baseline within minutes. During these instantaneous spikes, synchronous inventory commitment and payment processing saturate the web tier, causing timeouts and duplicate orders. Conversely, the overnight window (02:00 to 06:00) is nearly idle, so the always-on two-instance setup wastes cost during quiet hours.","As non-functional requirements, order API availability must be at least 99.95% monthly, P95 response time for key pages must be within 300 milliseconds, the RPO for payment-related data must be within 5 minutes, and the RTO for a regional outage must be within 4 hours. In addition, a security audit flagged that the data store holding member PII and payment tokens must be isolated on a network unreachable directly from the internet, and encryption keys must be managed by the organization. The annual infrastructure budget is held flat while absorbing 3x traffic growth.","The current issues boil down to four points. First, the single-AZ, single-EIP, manually recovered web and DB tiers are clear single points of failure. Second, synchronous processing during spikes becomes a bottleneck, causing lost orders. Third, origin delivery of static content strains EC2 CPU and bandwidth, threatening the response-time target. Fourth, there is effectively no recovery mechanism for a regional outage, so the RTO/RPO requirements cannot be met."]},"tables":[{"title":{"ja":"表1 現行構成と課題","en":"Table 1 Current Configuration and Issues"},"headers":{"ja":["コンポーネント","配置","主な課題"],"en":["Component","Placement","Key Issue"]},"rows":{"ja":[["Web/API（EC2 m5.xlarge ×2）","パブリックサブネット・単一AZ","単一AZ集中とEIP1つで冗長性なし"],["RDS for PostgreSQL（db.r5.large）","単一AZ・パブリック寄り","フェイルオーバー不可・直接到達可能"],["静的コンテンツ（画像/動画）","EC2ローカルディスク","帯域とCPUを圧迫し遅延増"],["バックアップ","日次RDSスナップショットのみ","アプリ層は手動再構築でRTO長い"]],"en":[["Web/API (EC2 m5.xlarge x2)","Public subnet, single AZ","Single-AZ concentration, one EIP, no redundancy"],["RDS for PostgreSQL (db.r5.large)","Single AZ, near public","No failover, directly reachable"],["Static content (images/videos)","EC2 local disk","Strains bandwidth and CPU, adds latency"],["Backup","Daily RDS snapshots only","App tier rebuilt manually, long RTO"]]}},{"title":{"ja":"表2 トラフィック・負荷特性","en":"Table 2 Traffic and Load Characteristics"},"headers":{"ja":["時間帯","平均リクエスト（RPS）","ピーク倍率","特性"],"en":["Time Window","Avg Requests (RPS)","Peak Multiplier","Characteristic"]},"rows":{"ja":[["日中（10-17時）","1,200","1.5倍","安定した通常負荷"],["夜間ピーク（18-21時）","4,500","8-11倍","スパイクで飽和・二重注文"],["深夜（2-6時）","150","0.1倍","ほぼアイドルで過剰コスト"],["月間注文数","約620万件","-","前年比3.2倍で増加中"]],"en":[["Daytime (10-17h)","1,200","1.5x","Stable normal load"],["Evening peak (18-21h)","4,500","8-11x","Saturation and duplicate orders on spikes"],["Overnight (2-6h)","150","0.1x","Nearly idle, over-provisioned cost"],["Monthly orders","~6.2 million","-","Growing 3.2x year over year"]]}},{"title":{"ja":"表3 非機能要件","en":"Table 3 Non-Functional Requirements"},"headers":{"ja":["項目","目標値","現状"],"en":["Item","Target","Current State"]},"rows":{"ja":[["注文API可用性","月間99.95%以上","単一AZ依存で未達"],["主要ページP95応答","300ミリ秒以内","静的配信で悪化し未達"],["決済データRPO","5分以内","日次バックアップのみ"],["リージョン障害RTO","4時間以内","復旧手段なし"]],"en":[["Order API availability","At least 99.95% monthly","Not met due to single-AZ dependency"],["Key page P95 response","Within 300 ms","Not met, degraded by static delivery"],["Payment data RPO","Within 5 minutes","Daily backup only"],["Regional outage RTO","Within 4 hours","No recovery mechanism"]]}},{"title":{"ja":"表4 DR方式の選択肢比較","en":"Table 4 DR Strategy Options Comparison"},"headers":{"ja":["方式","概算月額増","想定RTO","想定RPO"],"en":["Strategy","Approx. Monthly Cost Increase","Expected RTO","Expected RPO"]},"rows":{"ja":[["バックアップ&リストア","低（+8%）","12〜24時間","24時間"],["パイロットライト","中（+18%）","1〜4時間","数分"],["ウォームスタンバイ","高（+45%）","10〜30分","数分"],["マルチサイトアクティブ","最高（+90%）","ほぼ0","ほぼ0"]],"en":[["Backup & Restore","Low (+8%)","12-24 hours","24 hours"],["Pilot Light","Medium (+18%)","1-4 hours","A few minutes"],["Warm Standby","High (+45%)","10-30 minutes","A few minutes"],["Multi-site Active","Highest (+90%)","Near zero","Near zero"]]}}],"questions":[{"n":1,"q":{"ja":"Web/API層の単一障害点を除去し、可用性99.95%を満たしつつ夜間ピークのスパイクを吸収したい。最も適切な設計はどれか。","en":"You want to remove the single point of failure in the web/API tier and absorb evening peak spikes while meeting 99.95% availability. Which design is most appropriate?"},"options":[{"label":{"ja":"Application Load Balancerの背後に複数AZのAuto Scalingグループを置き、負荷に応じEC2を増減する。","en":"Place an Auto Scaling group spanning multiple AZs behind an Application Load Balancer and scale EC2 in and out based on load."},"ok":true,"exp":{"ja":"ALBが複数AZへ負荷分散し、Auto Scalingが台数を需要に追従させるため、AZ障害耐性とスパイク吸収と閑散時のコスト削減を同時に満たす。99.95%要件に合致する標準的なWell-Architected構成。","en":"The ALB distributes across multiple AZs and Auto Scaling tracks demand, simultaneously providing AZ fault tolerance, spike absorption, and cost savings during quiet hours, matching the 99.95% requirement in a standard Well-Architected pattern."}},{"label":{"ja":"既存の2台をより大きなインスタンスタイプへ垂直スケールし、同一AZ内で台数を4台に増やしてElastic IPを各インスタンスへ割り当てる。","en":"Vertically scale the two existing instances to a larger type, increase the count to four within the same AZ, and assign an Elastic IP to each instance."},"ok":false,"exp":{"ja":"台数を増やしても単一AZのままではAZ障害で全滅し99.95%を満たせない。垂直スケールはスパイクへの即応性に乏しく、複数EIP直割り当ては負荷分散もヘルスチェックも提供しない。","en":"Adding instances within a single AZ still fails entirely on an AZ outage and cannot meet 99.95%. Vertical scaling responds poorly to spikes, and directly assigning multiple EIPs provides neither load balancing nor health checks."}},{"label":{"ja":"AWS Global Acceleratorを前段に導入し、単一AZの固定2台へ静的エニーキャストIPで安定的にトラフィックを転送する。","en":"Introduce AWS Global Accelerator in front and steadily forward traffic to the fixed two instances in a single AZ via static anycast IPs."},"ok":false,"exp":{"ja":"Global Acceleratorはネットワーク経路を最適化するが、背後が固定2台・単一AZのままでは冗長性もオートスケールも得られず、単一障害点とスパイク問題は未解決のまま。","en":"Global Accelerator optimizes network paths but, with a fixed two-instance single-AZ backend, provides no redundancy or autoscaling, leaving the SPOF and spike problems unresolved."}},{"label":{"ja":"CloudFrontを注文APIの前段に置き、TTLを長めに設定してAPI応答をエッジにキャッシュすることでオリジン負荷を平準化する。","en":"Place CloudFront in front of the order API and cache API responses at the edge with a long TTL to smooth origin load."},"ok":false,"exp":{"ja":"注文APIは在庫や決済を含む動的・個別の応答でありキャッシュに適さず、長いTTLは在庫不整合や二重注文を悪化させる。オリジン側の単一AZ・単一障害点も解消されない。","en":"The order API returns dynamic, per-user responses involving inventory and payment that are unsuitable for caching; a long TTL worsens inventory inconsistency and duplicate orders, and the single-AZ SPOF at the origin remains."}}]},{"n":2,"q":{"ja":"単一AZのRDS for PostgreSQLの可用性を高め、決済データのRPO5分以内と読み取り増加への対応を両立したい。最も適切な選択はどれか。","en":"You want to improve the availability of the single-AZ RDS for PostgreSQL while meeting the 5-minute RPO for payment data and handling read growth. Which choice is most appropriate?"},"options":[{"label":{"ja":"RDSをMulti-AZ配置に変更し、参照系の負荷にはリードレプリカを追加してアプリの読み取りを振り分ける。","en":"Convert RDS to a Multi-AZ deployment and add read replicas for read-heavy workloads, routing application reads to them."},"ok":true,"exp":{"ja":"Multi-AZは同期レプリケーションで自動フェイルオーバーし、RPOをほぼ0（要件の5分以内を満たす）にする。リードレプリカで参照負荷を分離でき、可用性と読み取りスケールを両立する。","en":"Multi-AZ replicates synchronously with automatic failover, bringing RPO to near zero (within the 5-minute requirement). Read replicas offload read traffic, satisfying both availability and read scaling."}},{"label":{"ja":"単一AZのまま自動スナップショット頻度を上げ、別AZに手動スタンバイを用意して障害時にスナップショットから昇格させる運用にする。","en":"Keep single-AZ but increase automated snapshot frequency, prepare a manual standby in another AZ, and promote from a snapshot at failure time."},"ok":false,"exp":{"ja":"スナップショットは時点バックアップであり、復元・昇格には時間がかかりRPOもスナップショット間隔に依存して5分を満たしにくい。手動運用は自動フェイルオーバーに劣り可用性目標に届かない。","en":"Snapshots are point-in-time backups; restore and promotion take time, and RPO depends on the snapshot interval, making the 5-minute target hard to meet. Manual operation is inferior to automatic failover and misses the availability goal."}},{"label":{"ja":"書き込みと読み取りの双方をDynamoDBグローバルテーブルへ全面移行し、PostgreSQL依存を排除して水平スケールを得る。","en":"Fully migrate both writes and reads to DynamoDB global tables to eliminate PostgreSQL dependency and gain horizontal scale."},"ok":false,"exp":{"ja":"リレーショナルなトランザクション整合が必要な注文・決済をDynamoDBへ全面移行するのは大規模改修で、要件は可用性向上でありデータモデル変更ではない。過剰かつリスクの高い選択。","en":"Fully migrating transactional order/payment data requiring relational consistency to DynamoDB is a large rewrite; the requirement is improved availability, not a data-model change. It is excessive and risky."}},{"label":{"ja":"リードレプリカを複数AZに追加して参照を分散し、書き込みプライマリは単一AZのまま据え置いて監視を強化する。","en":"Add read replicas across multiple AZs to distribute reads while leaving the write primary in a single AZ and strengthening monitoring."},"ok":false,"exp":{"ja":"リードレプリカは読み取りスケールには有効だが非同期であり、プライマリが単一AZのままでは書き込み系の単一障害点と自動フェイルオーバー欠如が残り、可用性とRPO要件を満たせない。","en":"Read replicas help read scaling but are asynchronous; leaving the primary single-AZ retains the write-side SPOF and lacks automatic failover, failing the availability and RPO requirements."}}]},{"n":3,"q":{"ja":"商品画像や販促動画の配信でEC2の帯域とCPUが逼迫し、P95応答300ミリ秒を脅かしている。静的配信を最適化する最適な方法はどれか。","en":"Delivery of product images and promotional videos strains EC2 bandwidth and CPU, threatening the 300 ms P95 target. What is the best way to optimize static delivery?"},"options":[{"label":{"ja":"静的コンテンツをS3へ移し、CloudFront経由で配信してOrigin Access Controlでバケットを保護する。","en":"Move static content to S3, deliver it via CloudFront, and protect the bucket with Origin Access Control."},"ok":true,"exp":{"ja":"S3が耐久性の高いオリジンとなりEC2から配信負荷を切り離し、CloudFrontのエッジキャッシュがレイテンシを短縮してP95目標に寄与する。OACによりS3への直接アクセスを遮断でき安全。","en":"S3 becomes a durable origin, offloading delivery from EC2, while CloudFront edge caching reduces latency to help the P95 target. OAC blocks direct S3 access for security."}},{"label":{"ja":"各EC2にElastiCacheを併設して画像バイナリをメモリにキャッシュし、EC2からの配信を継続しつつ応答速度の向上を図る。","en":"Attach ElastiCache to each EC2 to cache image binaries in memory and continue serving from EC2 while improving response speed."},"ok":false,"exp":{"ja":"ElastiCacheはDBクエリ等のキャッシュ向けで大容量の静的バイナリ配信には不適であり、配信自体はEC2の帯域とCPUを消費し続けるため根本原因を解消しない。","en":"ElastiCache is meant for caching DB queries, not serving large static binaries; delivery still consumes EC2 bandwidth and CPU, so the root cause remains."}},{"label":{"ja":"静的コンテンツをEBSの高スループットなgp3ボリュームへ移し、EC2のI/Oを強化して配信スループットを底上げする。","en":"Move static content to high-throughput gp3 EBS volumes and boost EC2 I/O to raise delivery throughput."},"ok":false,"exp":{"ja":"gp3はディスクI/Oを改善するが、配信は依然EC2のネットワーク帯域とCPUを経由し、エッジ配信もオフロードも得られない。スケールと単一AZの弱点はそのまま残る。","en":"gp3 improves disk I/O, but delivery still traverses EC2 network bandwidth and CPU with no edge distribution or offload. The scaling and single-AZ weaknesses remain."}},{"label":{"ja":"静的コンテンツをS3へ移すが、CloudFrontは使わずS3の静的ウェブサイトホスティングを公開して直接配信する構成にする。","en":"Move static content to S3 but skip CloudFront, exposing S3 static website hosting to serve directly."},"ok":false,"exp":{"ja":"EC2負荷は減るがエッジキャッシュがないためレイテンシ短縮効果は限定的で、S3静的ホスティングは公開必須でありOACのようなアクセス制御や独自ドメインのTLS最適化に劣る。","en":"EC2 load drops, but without edge caching the latency benefit is limited, and S3 static hosting must be public, lacking access controls like OAC and optimized custom-domain TLS."}}]},{"n":4,"q":{"ja":"スパイク時に同期的な在庫確定・決済処理がWeb層を飽和させ、タイムアウトと二重注文が起きている。疎結合でスパイクを吸収する最適解はどれか。","en":"During spikes, synchronous inventory commitment and payment processing saturate the web tier, causing timeouts and duplicate orders. What is the best decoupled way to absorb spikes?"},"options":[{"label":{"ja":"注文をSQSキューに投入し、キュー長に応じてスケールするワーカーで非同期に在庫確定と決済を処理する。","en":"Enqueue orders into an SQS queue and process inventory commitment and payment asynchronously with workers that scale on queue depth."},"ok":true,"exp":{"ja":"SQSがスパイクをバッファしてWeb層を保護し、ワーカーがキュー長メトリクスで自動スケールして負荷を平準化する。メッセージの一意処理で二重注文も抑制でき、疎結合要件に最適。","en":"SQS buffers spikes to protect the web tier, and workers autoscale on queue-depth metrics to level the load. Unique message processing curbs duplicate orders, making it ideal for the decoupling requirement."}},{"label":{"ja":"注文イベントをSNSトピックへ発行し、複数のHTTPエンドポイントへファンアウトして各サブスクライバが即時に同期処理を行う。","en":"Publish order events to an SNS topic and fan out to multiple HTTP endpoints where each subscriber processes synchronously in real time."},"ok":false,"exp":{"ja":"SNSはファンアウト通知向けでバッファリングやリトライによる負荷平準化を主目的とせず、購読側が同期処理では下流が飽和する。スパイク吸収にはキューによる緩衝が必要。","en":"SNS is for fan-out notification, not load leveling via buffering and retry; if subscribers process synchronously, downstream saturates. Absorbing spikes requires a queue as a buffer."}},{"label":{"ja":"Web層のAuto Scalingの上限を大幅に引き上げ、スパイク時に多数のインスタンスを起動して同期処理のスループットで受け切る。","en":"Sharply raise the web tier's Auto Scaling maximum and launch many instances during spikes to handle the throughput with synchronous processing."},"ok":false,"exp":{"ja":"起動には時間がかかり数分の瞬間スパイクに追従できず、下流のDBや決済APIも同時に飽和する恐れがある。同期のままでは二重注文の根本解決にならずコストも急増する。","en":"Instance launches take time and cannot follow multi-minute instantaneous spikes, and downstream DB and payment APIs may saturate too. Staying synchronous does not fundamentally fix duplicate orders and cost surges."}},{"label":{"ja":"在庫確定処理をRDSのストアドプロシージャに集約し、行ロックとトランザクションで二重注文を防止して整合性を担保する。","en":"Consolidate inventory commitment into RDS stored procedures, preventing duplicate orders with row locks and transactions to ensure consistency."},"ok":false,"exp":{"ja":"行ロックは整合性には寄与するが、スパイク時にDBがロック競合で逆にボトルネック化し、Web層の飽和とタイムアウトは解消しない。疎結合による負荷緩衝という要件を満たさない。","en":"Row locks aid consistency but, under spikes, the DB becomes a bottleneck due to lock contention, and web-tier saturation and timeouts persist. It does not meet the requirement of load buffering via decoupling."}}]},{"n":5,"q":{"ja":"リージョン障害時のRTO4時間以内・RPO5分以内を、年間予算据え置きの制約下で満たしたい。表4を踏まえた最も適切なDR方式はどれか。","en":"You must meet RTO within 4 hours and RPO within 5 minutes for a regional outage under a flat annual budget. Given Table 4, which DR strategy is most appropriate?"},"options":[{"label":{"ja":"別リージョンにパイロットライトを構築し、RDSのクロスリージョンレプリカで最小構成を維持して障害時に拡張・昇格する。","en":"Build a pilot light in another region, keep a minimal footprint with a cross-region RDS replica, and scale out and promote at failover."},"ok":true,"exp":{"ja":"パイロットライトはコアのDBを継続レプリケーションしRPOを数分に保ちつつ、通常時は最小構成で低コスト。障害時にアプリ層を拡張して1〜4時間で復旧でき、RTO4時間・予算据え置きの両要件に合致する。","en":"Pilot light continuously replicates the core DB to keep RPO to minutes while running minimally at low cost; at failover the app tier scales out to recover in 1-4 hours, matching both the 4-hour RTO and the flat budget."}},{"label":{"ja":"コスト最小のバックアップ&リストア方式を採用し、日次スナップショットを別リージョンへコピーして障害時に一から環境を復元する。","en":"Adopt the lowest-cost backup-and-restore approach, copy daily snapshots to another region, and rebuild the environment from scratch at failover."},"ok":false,"exp":{"ja":"最も安価だがRTOが12〜24時間、RPOも日次で24時間相当となり、4時間・5分の要件をいずれも満たせない。コストのみを優先して復旧目標を外す典型的な過小投資。","en":"It is cheapest but yields RTO of 12-24 hours and RPO of about 24 hours from daily backups, meeting neither the 4-hour nor the 5-minute target. It is classic under-investment that prioritizes cost and misses recovery goals."}},{"label":{"ja":"別リージョンにウォームスタンバイを常時稼働させ、本番と同等規模の縮小版を維持して短時間で切り替えられるようにする。","en":"Run a warm standby in another region at all times, maintaining a scaled-down replica of production for quick cutover."},"ok":false,"exp":{"ja":"RTO10〜30分と要件を上回る復旧性を得られるが月額約+45%と高く、RTO4時間で足りる本件では予算据え置き制約に反する過剰投資となる。","en":"It achieves RTO of 10-30 minutes, exceeding the requirement, but at roughly +45% monthly it is over-investment that violates the flat-budget constraint when a 4-hour RTO suffices."}},{"label":{"ja":"複数リージョンでのマルチサイトアクティブ構成を採用し、両リージョンで本番トラフィックを常時処理して即時フェイルオーバーを実現する。","en":"Adopt a multi-site active configuration across regions, serving production traffic in both regions at all times for instant failover."},"ok":false,"exp":{"ja":"RTO/RPOをほぼ0にできるが月額約+90%と最も高コストで、4時間・5分の要件に対し大幅な過剰投資となり予算据え置きの前提を明確に外す。","en":"It brings RTO/RPO to near zero but at roughly +90% monthly is the costliest, a substantial over-investment against 4-hour and 5-minute targets that clearly violates the flat-budget premise."}}]}]},{"id":"saa-2","title":{"ja":"OrbitPay 決済プラットフォーム: イベント駆動化とマルチリージョン DR 設計","en":"OrbitPay Settlement Platform: Event-Driven Redesign and Multi-Region DR"},"body":{"ja":["OrbitPay は東京(ap-northeast-1)を拠点に、日本と東南アジアの加盟店向けにカード決済と口座振替の即時決済・精算(元帳)サービスを提供するフィンテック企業である。現在は全システムを東京の単一リージョンで運用しており、大阪(ap-northeast-3)は災害対策として確保されているが未活用である。","現行アーキテクチャでは、フロントは ALB と ECS Fargate で構成され、決済受付 API がリクエストを受けると同期的に Aurora PostgreSQL(Multi-AZ)へ元帳を書き込む。通知・精算・不正検知といった後続処理は、受付 API から Lambda を直接同期呼び出しする密結合構成になっている。","この密結合が障害の温床である。ピーク時に不正検知サービスがスロットリングされると、その遅延が受付 API までブロックし、決済自体が失敗する。クライアントのリトライにより同一取引が二重に記帳され、二重課金の苦情が発生した。さらに並列処理で記帳順序が乱れ、同一口座の残高計算が一時的に不整合となる事象も報告された。","非機能要件は厳しい。元帳は口座単位で厳密な順序(FIFO)と強整合を要求し、決済受付の可用性は月間 99.95% を維持しなければならない。リージョン障害時でも元帳の RTO は 1 分以内、RPO は 1 秒以内が求められる。監査ログは 7 年間、改ざん不可(WORM)で保管する法規制がある。","トラフィックは平常時 2,000 TPS だが、月末精算日には 12,000 TPS までスパイクし、大型セール連動で最大 90 分継続する。同一口座への連続取引は必ず発生順に処理される必要があり、ネットワーク再送により平常 0.1%・ピーク 0.5% の重複配信が観測されている。","昨年、東京の単一 AZ 障害により決済が 22 分間停止し、SLA を割り込んだ。同時期に前述の二重課金インシデントが発生し、経営層は疎結合化・冪等性・順序保証・リージョン DR の全てを同時に満たす再設計を要求した。","一方でコスト制約も厳しく、DR を含む月額インフラ費用の上限は 10,000 USD に設定された。両リージョンにフルサイズの本番スタックを常時稼働させるアクティブ/アクティブは予算超過であり、要件に対する過剰設計と見なされる。コスト効率と要件充足の両立が絶対条件である。","あなたはソリューションアーキテクトとして、SQS/SNS/EventBridge による疎結合化、冪等性と口座単位の順序保証、マルチリージョン DR(RTO/RPO)、監査ログの不変保管を、コスト上限内で設計することを求められている。以下の資料に基づき設問に答えよ。"],"en":["OrbitPay is a fintech company based in Tokyo (ap-northeast-1) that provides real-time card and bank-transfer settlement and ledger services to merchants across Japan and Southeast Asia. All systems currently run in the single Tokyo Region; Osaka (ap-northeast-3) is reserved for disaster recovery but is unused.","In the current architecture, the front end is ALB plus ECS Fargate, and when the payment-intake API receives a request it synchronously writes the ledger to Aurora PostgreSQL (Multi-AZ). Downstream processing such as notifications, settlement, and fraud detection is tightly coupled: the intake API invokes Lambda functions directly and synchronously.","This tight coupling is the root of the failures. When the fraud-detection service is throttled at peak, its latency blocks all the way back to the intake API and payments themselves fail. Client retries cause the same transaction to be booked twice, producing double-charge complaints. Parallel processing has also disordered postings, temporarily making per-account balance calculations inconsistent.","The non-functional requirements are demanding. The ledger requires strict per-account ordering (FIFO) and strong consistency, and payment-intake availability must stay at 99.95% per month. Even during a Region failure the ledger RTO must be within 1 minute and RPO within 1 second. Regulation requires audit logs to be retained for 7 years in immutable (WORM) form.","Traffic is 2,000 TPS normally but spikes to 12,000 TPS on month-end settlement days, lasting up to 90 minutes during large sales events. Consecutive transactions on the same account must be processed strictly in arrival order, and network resends produce duplicate deliveries of 0.1% normally and 0.5% at peak.","Last year a single-AZ failure in Tokyo halted payments for 22 minutes and breached the SLA. The double-charge incident occurred around the same time, and management demanded a redesign that simultaneously delivers decoupling, idempotency, ordering guarantees, and cross-Region DR.","Cost constraints are also strict: the monthly infrastructure budget including DR is capped at 10,000 USD. Running full-size production stacks active/active in both Regions exceeds the budget and is considered over-engineering relative to the requirements. Balancing cost efficiency with requirement compliance is mandatory.","As the solutions architect, you must design decoupling with SQS/SNS/EventBridge, idempotency and per-account ordering, multi-Region DR (RTO/RPO), and immutable audit-log retention, all within the cost cap. Answer the questions based on the materials below."]},"tables":[{"title":{"ja":"資料1: 現行構成と主な課題","en":"Exhibit 1: Current components and key issues"},"headers":{"ja":["コンポーネント","現行実装","主な課題"],"en":["Component","Current implementation","Key issue"]},"rows":{"ja":[["決済受付API","ECS Fargate + ALB、後続を同期呼び出し","下流障害が受付まで伝播する"],["元帳DB","Aurora PostgreSQL Multi-AZ(東京単一)","リージョン障害でRTO/RPO未達"],["後続処理","Lambdaを直接同期呼び出し(密結合)","順序保証なし・二重実行が発生"],["通知/精算","同期処理でスロットリングに脆弱","スロットリングで受付が停止"],["監査ログ","RDSテーブルへ追記","改ざん耐性と長期保管が不足"]],"en":[["Payment-intake API","ECS Fargate + ALB, synchronous downstream calls","Downstream failures propagate to intake"],["Ledger DB","Aurora PostgreSQL Multi-AZ (Tokyo only)","Region failure misses RTO/RPO"],["Downstream processing","Direct synchronous Lambda calls (tight coupling)","No ordering; double execution occurs"],["Notification/settlement","Synchronous, fragile to throttling","Throttling halts intake"],["Audit log","Appended to an RDS table","Lacks tamper resistance and long retention"]]}},{"title":{"ja":"資料2: トラフィックとピーク特性","en":"Exhibit 2: Traffic and peak characteristics"},"headers":{"ja":["指標","平常時","ピーク時","備考"],"en":["Metric","Normal","Peak","Note"]},"rows":{"ja":[["決済スループット","2,000 TPS","12,000 TPS","月末精算日にスパイク"],["口座単位の順序","必須","必須","同一口座はFIFO厳守"],["メッセージサイズ","平均4KB","最大64KB","明細付き取引"],["スパイク継続時間","-","最大90分","大型セール連動"],["重複配信率","0.1%","0.5%","タイムアウト再送に起因"]],"en":[["Payment throughput","2,000 TPS","12,000 TPS","Spikes on month-end settlement"],["Per-account ordering","Required","Required","Same account must be FIFO"],["Message size","4KB avg","64KB max","Itemized transactions"],["Spike duration","-","Up to 90 min","Tied to large sales events"],["Duplicate delivery rate","0.1%","0.5%","Caused by timeout resends"]]}},{"title":{"ja":"資料3: 非機能要件と目標値","en":"Exhibit 3: Non-functional requirements and targets"},"headers":{"ja":["要件","目標値","対象"],"en":["Requirement","Target","Scope"]},"rows":{"ja":[["可用性","99.95%/月","決済受付"],["RTO","1分以内","元帳(リージョン障害)"],["RPO","1秒以内","元帳"],["整合性","強整合・口座単位FIFO","元帳/残高"],["監査保管","7年・WORM(改ざん不可)","監査ログ"]],"en":[["Availability","99.95%/month","Payment intake"],["RTO","Within 1 min","Ledger (Region failure)"],["RPO","Within 1 sec","Ledger"],["Consistency","Strong, per-account FIFO","Ledger/balance"],["Audit retention","7 years, WORM (immutable)","Audit log"]]}},{"title":{"ja":"資料4: DR方式候補の比較","en":"Exhibit 4: Comparison of DR approaches"},"headers":{"ja":["DR方式","平常コスト","RTO","RPO","整合性"],"en":["DR approach","Steady-state cost","RTO","RPO","Consistency"]},"rows":{"ja":[["バックアップ/リストア","低","数時間","数十分","復元時点まで巻き戻る"],["パイロットライト","中低","10〜30分","分単位","起動・復元後に整合"],["ウォームスタンバイ","中","数分","秒単位","準リアルタイム"],["Aurora Global Database","中高","1分未満","約1秒","単一ライターで強整合"],["DynamoDB Global Tables","高","秒単位","秒単位","マルチライターで結果整合(LWW)"]],"en":[["Backup/restore","Low","Hours","Tens of minutes","Rolls back to restore point"],["Pilot light","Low-mid","10-30 min","Minutes","Consistent after start/restore"],["Warm standby","Mid","Minutes","Seconds","Near real-time"],["Aurora Global Database","Mid-high","Under 1 min","~1 sec","Single writer, strong consistency"],["DynamoDB Global Tables","High","Seconds","Seconds","Multi-writer eventual consistency (LWW)"]]}},{"title":{"ja":"資料5: 提案構成の月額コスト内訳(概算)","en":"Exhibit 5: Proposed monthly cost breakdown (estimate)"},"headers":{"ja":["項目","構成","月額(USD)"],"en":["Item","Configuration","Monthly (USD)"]},"rows":{"ja":[["Auroraプライマリ(東京)","db.r6g.2xlarge×2 Multi-AZ","4,200"],["Auroraセカンダリ(大阪)","db.r6g.2xlarge レプリカ1台","2,100"],["SQS FIFO","高スループットモード・数億リクエスト","1,300"],["監査ログ保管","S3 Object Lock + Glacier階層","600"],["EventBridge他","ルール・データ転送・監視","900"],["合計(DR込み)","上限 10,000 USD","9,100"]],"en":[["Aurora primary (Tokyo)","db.r6g.2xlarge x2 Multi-AZ","4,200"],["Aurora secondary (Osaka)","db.r6g.2xlarge, 1 replica","2,100"],["SQS FIFO","High-throughput mode, ~hundreds of millions of requests","1,300"],["Audit-log retention","S3 Object Lock + Glacier tier","600"],["EventBridge and others","Rules, data transfer, monitoring","900"],["Total (incl. DR)","Cap 10,000 USD","9,100"]]}}],"questions":[{"n":1,"q":{"ja":"リージョン障害時にも元帳の RTO 1分以内・RPO 1秒以内・口座単位の強整合を満たすには、どの DR 方式を採用すべきか。","en":"Which DR approach satisfies the ledger's within-1-minute RTO, within-1-second RPO, and per-account strong consistency even during a Region failure?"},"options":[{"label":{"ja":"Aurora Global Database で大阪リージョンを読み取り専用セカンダリとし、管理フェイルオーバで昇格させる","en":"Use Aurora Global Database with Osaka as a read-only secondary and promote it via managed failover"},"ok":true,"exp":{"ja":"Aurora Global Database は単一ライターの強整合を保ちつつ、専用レプリケーション基盤で一般に RPO 約1秒、管理フェイルオーバで1分未満の昇格を実現する。RTO≤1分/RPO≤1秒/口座単位強整合をすべて満たす。","en":"Aurora Global Database keeps single-writer strong consistency while its dedicated replication typically gives ~1s RPO and sub-minute promotion via managed failover, satisfying RTO<=1min, RPO<=1s, and per-account strong consistency."}},{"label":{"ja":"DynamoDB Global Tables でマルチリージョン・マルチアクティブ化し、両リージョンで書き込みを受け付けて冗長化する","en":"Adopt DynamoDB Global Tables as multi-Region multi-active, accepting writes in both Regions for redundancy"},"ok":false,"exp":{"ja":"Global Tables はマルチアクティブで最終書き込み優先(LWW)の結果整合となり、口座残高の厳密順序と強整合を破壊する。RPO は良好でも整合性要件を決定的に外すため元帳には不適。","en":"Global Tables is multi-active with last-writer-wins eventual consistency, which breaks strict per-account ordering and strong consistency. Even with good RPO it decisively misses the consistency requirement, so it is unfit for the ledger."}},{"label":{"ja":"クロスリージョンの自動バックアップとスナップショットを用い、障害発生時に別リージョンで復元して復旧する","en":"Use cross-Region automated backups and snapshots, restoring in the other Region when a failure occurs"},"ok":false,"exp":{"ja":"バックアップ/リストアは RTO が数時間、RPO が数十分となり、RTO≤1分・RPO≤1秒を到底満たせない(資料4)。低コストだが要件を大きく外す。","en":"Backup/restore yields RTO of hours and RPO of tens of minutes, far from RTO<=1min and RPO<=1s (Exhibit 4). Cheap but grossly non-compliant."}},{"label":{"ja":"単一リージョン内の Multi-AZ 構成を強化し、読み取りレプリカを追加してさらに可用性を高める","en":"Strengthen single-Region Multi-AZ and add read replicas to further raise availability"},"ok":false,"exp":{"ja":"Multi-AZ は同一リージョン内の AZ 冗長化に過ぎず、リージョン全体の障害には無力。RTO/RPO のリージョン要件を満たせない。","en":"Multi-AZ only provides AZ redundancy within one Region and is powerless against a whole-Region failure, so it cannot meet the Region-level RTO/RPO."}}]},{"n":2,"q":{"ja":"受付 API と後続処理の密結合を解消しつつ、口座単位の順序保証と冪等性(重複配信対策)を実現する構成はどれか。","en":"Which design decouples the intake API from downstream processing while providing per-account ordering and idempotency against duplicate delivery?"},"options":[{"label":{"ja":"SQS FIFO を用い、口座IDをメッセージグループIDにして順序保証し、重複排除で冪等化する","en":"Use SQS FIFO with the account ID as the message group ID for ordering, and deduplication for idempotency"},"ok":true,"exp":{"ja":"SQS FIFO はメッセージグループID単位で厳密順序を保証し、コンテンツベース重複排除で at-least-once の再送を冪等化する。受付 API をキューで分離するため下流障害の伝播も断てる。","en":"SQS FIFO guarantees strict order per message group ID and makes at-least-once resends idempotent via content-based deduplication. Decoupling the intake API through the queue also stops downstream failures from propagating."}},{"label":{"ja":"SNS 標準トピックで下流へファンアウトし、各コンシューマがベストエフォートでメッセージを処理する","en":"Fan out to downstream via an SNS standard topic and let each consumer process messages best-effort"},"ok":false,"exp":{"ja":"SNS 標準トピックは順序を保証せず、ファンアウトはできても口座単位 FIFO を満たせない。冪等性も別途担保が必要で要件を外す。","en":"An SNS standard topic does not guarantee ordering; fan-out is fine but per-account FIFO is not met, and idempotency must be handled separately, missing the requirement."}},{"label":{"ja":"SQS 標準キューへ切り替えてスループットを最大化し、タイムスタンプでコンシューマ側が並べ替える","en":"Switch to SQS standard queues to maximize throughput and reorder on the consumer side using timestamps"},"ok":false,"exp":{"ja":"標準キューは順序を保証せず、コンシューマ側の並べ替えは並列スケール時に破綻する。高スループットは魅力的だが順序要件を決定的に外す。","en":"Standard queues do not guarantee order, and consumer-side reordering breaks down under parallel scaling. The high throughput is tempting but it decisively fails the ordering requirement."}},{"label":{"ja":"Kinesis Data Streams の単一シャードに全トランザクションを流し込み、直列に順序化して処理する","en":"Feed all transactions into a single Kinesis Data Streams shard and process them serially in order"},"ok":false,"exp":{"ja":"単一シャードは順序化できるが書き込み約1MB/s・1,000レコード/sが上限で、12,000 TPS に到底届かずスループットで破綻する。","en":"A single shard can order records but caps at ~1MB/s and 1,000 records/s, nowhere near 12,000 TPS, so it fails on throughput."}}]},{"n":3,"q":{"ja":"ピーク 12,000 TPS を、口座単位の FIFO 順序を保ったまま処理するための最適な構成はどれか。","en":"What is the best design to process peak 12,000 TPS while preserving per-account FIFO ordering?"},"options":[{"label":{"ja":"SQS FIFO の高スループットモードを有効化し、口座IDを多数のグループへ分散して並列処理する","en":"Enable SQS FIFO high-throughput mode and spread account IDs across many groups for parallel processing"},"ok":true,"exp":{"ja":"高スループットモードは1キューで最大数万メッセージ/秒を提供し、口座IDを多数のメッセージグループへ分散すればグループ間で並列化しつつグループ内順序を保てる。12,000 TPS と FIFO を両立する。","en":"High-throughput mode provides up to tens of thousands of messages/s per queue, and spreading account IDs across many message groups parallelizes across groups while preserving order within each, meeting both 12,000 TPS and FIFO."}},{"label":{"ja":"単一のメッセージグループIDへ全件を集約して厳密な全体順序を保証し、バッチ送信で最大スループットを狙う","en":"Aggregate everything into a single message group ID for strict global order and batch sends to maximize throughput"},"ok":false,"exp":{"ja":"単一グループは全体順序を強いるためスループットが約300 msg/s(バッチで最大3,000)に制限され、12,000 TPS に届かない。要件にない全体順序を課す過剰設計。","en":"A single group forces global order and caps throughput at ~300 msg/s (up to 3,000 with batching), far below 12,000 TPS. It over-orders beyond what is required."}},{"label":{"ja":"高スループットを無効化した FIFO を複数キューへ手動シャーディングして合算スループットを確保する","en":"Manually shard non-high-throughput FIFO queues across many queues to sum up throughput"},"ok":false,"exp":{"ja":"既定モードの FIFO は約300 msg/s のため多数キューへの手動シャーディングが必要になり、運用が複雑。高スループットモードで解決できるため非効率で不要。","en":"Default-mode FIFO is ~300 msg/s, requiring many manually sharded queues and operational complexity. High-throughput mode solves this, making manual sharding inefficient and unnecessary."}},{"label":{"ja":"Lambda の予約同時実行を引き上げ、キューを介さずに受付から下流を同期的に呼び出して処理する","en":"Raise Lambda reserved concurrency and call downstream synchronously from intake without a queue"},"ok":false,"exp":{"ja":"キューを介さない同期処理は疎結合とバッファリングを失い、スパイク時に受付 API がブロックして停止する。順序保証もない。","en":"Queueless synchronous processing loses decoupling and buffering, so the intake API blocks and stalls during spikes, and there is no ordering guarantee."}}]},{"n":4,"q":{"ja":"監査ログを 7 年間、改ざん不可(WORM)で保管する要件を満たす方式はどれか。","en":"Which approach satisfies retaining audit logs for 7 years in immutable (WORM) form?"},"options":[{"label":{"ja":"S3 の Object Lock コンプライアンスモードで保管し、ライフサイクルで Glacier へ移行する","en":"Store with S3 Object Lock in compliance mode and transition to Glacier via lifecycle rules"},"ok":true,"exp":{"ja":"Object Lock のコンプライアンスモードは root を含め誰も保持期間中の削除・上書きを行えない WORM を提供し、ライフサイクルで Glacier 階層へ移行して7年を低コスト保持できる。","en":"Object Lock compliance mode provides WORM that no one, not even root, can delete or overwrite during the retention period, and lifecycle transition to Glacier retains 7 years at low cost."}},{"label":{"ja":"DynamoDB に IAM ポリシーで削除を制限したテーブルを作り、ストリームで別テーブルへ複製して長期保管する","en":"Create a DynamoDB table with deletes restricted by IAM policy and replicate via streams to another table for long-term retention"},"ok":false,"exp":{"ja":"IAM ポリシーは変更可能で真の WORM ではなく、改ざん不可要件を満たさない。複製してもオブジェクトの不変性は保証されない。","en":"IAM policies are mutable and are not true WORM, so they fail immutability. Replication does not guarantee object-level immutability either."}},{"label":{"ja":"CloudTrail を有効化してログを記録し、S3 標準バケットへ無期限に保管して監査に用いる","en":"Enable CloudTrail to record logs and retain them indefinitely in a standard S3 bucket for auditing"},"ok":false,"exp":{"ja":"CloudTrail は AWS API 操作の監査用でありアプリ元帳の監査ログとは用途が異なる。WORM や 7 年のライフサイクルも別途必要で要件を外す。","en":"CloudTrail audits AWS API activity, not application ledger audit logs, and still needs separate WORM and 7-year lifecycle, missing the requirement."}},{"label":{"ja":"S3 のバージョニングと MFA Delete のみを有効化し、誤削除を防ぎながらオブジェクトを保持する","en":"Enable only S3 versioning and MFA Delete to prevent accidental deletion while retaining objects"},"ok":false,"exp":{"ja":"バージョニング+MFA Delete は誤削除を抑止するがコンプライアンス級の不変保持ではなく、権限保持者は削除可能で WORM 要件を満たさない。","en":"Versioning plus MFA Delete deters accidental deletion but is not compliance-grade immutability; privileged holders can still delete, failing WORM."}}]},{"n":5,"q":{"ja":"月額上限 10,000 USD の制約下で、元帳の RTO/RPO を満たしつつ最もコスト効率が高い DR 構成はどれか。","en":"Under the 10,000 USD monthly cap, which DR design meets the ledger RTO/RPO while being the most cost-efficient?"},"options":[{"label":{"ja":"Aurora Global のセカンダリ1台と FIFO・S3 で構成し、概算 9,100 USD に収める","en":"Build with one Aurora Global secondary plus FIFO and S3, landing at ~9,100 USD"},"ok":true,"exp":{"ja":"Aurora Global のセカンダリ1台+SQS FIFO+S3 Object Lock は資料5の概算 9,100 USD で上限 10,000 内。RTO≤1分/RPO≤1秒/強整合を満たしつつコスト効率が高い。","en":"One Aurora Global secondary plus SQS FIFO plus S3 Object Lock is ~9,100 USD (Exhibit 5), within the 10,000 cap, and meets RTO<=1min, RPO<=1s, and strong consistency cost-efficiently."}},{"label":{"ja":"両リージョンにフルサイズの本番同等スタックを常時稼働させ、アクティブ/アクティブ構成で全体の可用性を最大化する","en":"Run full-size production-equivalent stacks in both Regions active/active to maximize overall availability"},"ok":false,"exp":{"ja":"両リージョン本番同等の常時稼働は上限 10,000 USD を大きく超過し、要件(RTO≤1分は単一ライター昇格で足りる)に対する過剰設計。コスト非効率で不適。","en":"Always-on production-equivalent in both Regions far exceeds the 10,000 cap and over-engineers relative to the requirement (single-writer promotion suffices for RTO<=1min), so it is cost-inefficient."}},{"label":{"ja":"バックアップ/リストア方式でコストを最小化し、障害発生時にスナップショットから復旧する","en":"Minimize cost with backup/restore and recover from a snapshot when a failure occurs"},"ok":false,"exp":{"ja":"最安だが RTO が数時間で 1 分以内を満たせない。コストのみを優先して要件を外す典型的なワナ。","en":"Cheapest but RTO is hours, failing within-1-minute. A classic trap of optimizing cost only and missing the requirement."}},{"label":{"ja":"パイロットライト方式でセカンダリの DB を停止しておき、障害発生時に起動して昇格させる","en":"Keep the secondary DB stopped as pilot light and start then promote it on failure"},"ok":false,"exp":{"ja":"パイロットライトは起動・昇格に 10〜30 分かかり(資料4)、RTO 1 分以内を満たせない。","en":"Pilot light takes 10-30 minutes to start and promote (Exhibit 4), failing the within-1-minute RTO."}}]},{"n":6,"q":{"ja":"精算・通知・不正検知の各下流へイベントを配信し、ターゲット別ルーティング・スキーマ管理・失敗メッセージの隔離を行う構成はどれか。","en":"Which design delivers events to settlement, notification, and fraud-detection downstreams with per-target routing, schema management, and isolation of failed messages?"},"options":[{"label":{"ja":"EventBridge のバスへ発行し、ルールでターゲット別に振り分け、失敗は DLQ へ退避する","en":"Publish to an EventBridge bus, route per target with rules, and send failures to a DLQ"},"ok":true,"exp":{"ja":"EventBridge はスキーマレジストリとルールでターゲット別にルーティングでき、配信失敗はターゲット単位の DLQ(SQS)へ隔離できる。疎結合と可観測性を両立する。","en":"EventBridge routes per target with rules and a schema registry, and isolates delivery failures to per-target DLQs (SQS), balancing decoupling and observability."}},{"label":{"ja":"受付 Lambda から各下流サービスの API を同期的に直接呼び出し、失敗時はアプリ内でリトライを繰り返す","en":"Call each downstream service API synchronously and directly from the intake Lambda, retrying in-app on failure"},"ok":false,"exp":{"ja":"同期直接呼び出しは密結合に逆戻りし、下流障害が受付へ伝播する。ルーティングもスキーマ管理も隔離も得られず現行課題を再現する。","en":"Direct synchronous calls revert to tight coupling and let downstream failures propagate to intake, with no routing, schema management, or isolation, reproducing the current problem."}},{"label":{"ja":"SNS 標準トピックへ全イベントを送信し、フィルタを使わず全コンシューマへ無差別に配信する","en":"Send all events to an SNS standard topic and broadcast to all consumers without filtering"},"ok":false,"exp":{"ja":"フィルタ未使用の無差別配信ではターゲット別ルーティングやスキーマ検証の要件を満たせず、各下流が不要イベントも受信する。","en":"Undifferentiated broadcast without filtering fails per-target routing and schema validation, and each downstream receives events it does not need."}},{"label":{"ja":"単一の SQS キューへ全イベントを入れ、各下流がポーリングして自分宛かどうかを判別する","en":"Put all events into a single SQS queue and have each downstream poll and decide if it is the intended target"},"ok":false,"exp":{"ja":"単一キューの競合コンシューマはファンアウトにならず、あるコンシューマが取得したメッセージを他が受け取れない。全下流への配信要件を満たせない。","en":"Competing consumers on one queue do not fan out; a message taken by one consumer is unavailable to others, so it cannot deliver to all downstreams."}}]}]},{"id":"saa-3","title":{"ja":"グローバルOTT/メディアSaaS「Auralis Media」— データレジデンシ準拠のコンテンツ配信・セキュリティ再設計","en":"Global OTT / Media SaaS \"Auralis Media\" — Redesigning Content Delivery and Security under Data Residency Constraints"},"body":{"ja":["Auralis Media Group は、消費者向けの映像ストリーミング(OTT)と、法人向けの映像制作・配信を支援するメディアSaaSを同一プラットフォーム上で運営している。契約者は EU、日本、ブラジル、インド、北米の5地域に分布し、月間アクティブ視聴者は 4,200 万人、法人テナントは 1,800 社に達する。プラットフォームは AWS 上で us-east-1 を中心に構築され、配信は Amazon CloudFront、原本ストレージは Amazon S3、メタデータと視聴履歴は各地域の RDS/DynamoDB に格納されている。近年の地域規制強化と急激なトラフィック増により、現行構成は規制・レイテンシ・コスト・権限管理のいずれの面でも限界が見え始めている。","最大の制約はデータレジデンシである。EU の契約者に紐づく個人データ(氏名、決済情報、視聴履歴)は EU リージョン内に保管しなければならず、暗号鍵も EU 内で管理・失効できることが監査要件になっている。ブラジルの LGPD、インドのデータ保護規則も同様に「規制対象データの国外持ち出し制限」を課す。一方で、映像の原本(マスターファイル)自体は個人データを含まないため、コスト効率を理由に集約保管したいという配信チームの要望がある。しかし法務部門は『地域を跨ぐ複製は監査説明が煩雑になる』として、規制対象データと非規制データの境界を構成上も明確に分離することを強く求めている。","非機能要件も厳しい。消費者向け再生開始レイテンシ(TTFB)は各地域で p95 400 ミリ秒以内、ライブ配信の可用性は 99.95% が SLA として顧客に約束されている。法人SaaS の管理コンソールとアップロードAPIは、テナントの一部が『インターネットを経由しない専用経路での接続』を契約条件としており、パブリックエンドポイント経由の接続を監査で問題視されている。加えて、直近のペネトレーションテストで、S3 オリジンバケットがCloudFront以外からも直接到達可能な状態であること、IAM ロールの一部が `s3:*` や `kms:*` を広域リソースに対して許可していることが指摘された。","現行のオリジン負荷も課題である。CloudFront のキャッシュヒット率は地域平均で 78% にとどまり、特に法人向けの動的サムネイル生成とマニフェスト配信でオリジンへの往復が多発している。ピーク時には S3 と背後の Lambda@Edge/オリジンサービスへのリクエストが集中し、オリジン側のスケール限界と S3 データ転送(egress)コストの双方が問題化している。北米リージョンのオリジンに対して他地域から直接フェッチが発生しているケースもあり、これはレイテンシとコストの両面で非効率であると同時に、地域データ境界の観点でも望ましくない。","権限管理の現状はさらに深刻だ。開発・運用・データ分析の各チームが単一AWSアカウント内で作業しており、分析チームの IAM ユーザーが本番の暗号鍵と原本バケットに広い権限を持つ。テナント運用の自動化ロールは、本来自テナントのプレフィックスのみ触れれば十分なのに、バケット全体への読み書きが付与されている。セキュリティ部門は『最小権限とタグベースの権限分離(ABAC)、および権限昇格を構造的に防ぐ仕組み』を再設計の必須条件として掲げている。","コスト面では、CloudFront の料金クラスが全世界(All edge locations)に設定されているにもかかわらず、実トラフィックの 96% は上記5地域に集中している。S3 は全リージョンで S3 Standard を使用しており、90 日以上アクセスされない原本マスターが総容量の 62% を占める。RDS はマルチAZ構成だが、分析用の重いクエリが本番トランザクションと同一インスタンスに相乗りし、コストとパフォーマンスの両方を悪化させている。CFO は『規制と SLA を一切妥協せずに、月間インフラコストを 25% 削減する』ことを経営目標として設定した。","経営会議では要望が衝突している。配信チームは低レイテンシと単純な集約構成を、法務・セキュリティ部門は厳格な地域分離と最小権限を、財務部門はコスト削減を、それぞれ最優先に主張する。あなたはリードソリューションアーキテクトとして、これらの相反要求を1つの参照アーキテクチャに統合し、『どの要件も決定的に破らない』設計判断を各領域で下すことを求められている。以降の設問では、複数の資料表を横断して、規制・レイテンシ・権限・コストの制約を同時に満たす選択肢を1つだけ選ぶこと。"],"en":["Auralis Media Group runs both a consumer video streaming (OTT) service and a B2B media SaaS for production and distribution on a single platform. Subscribers span five regions — EU, Japan, Brazil, India, and North America — with 42 million monthly active viewers and 1,800 corporate tenants. The platform is built on AWS centered on us-east-1, delivery uses Amazon CloudFront, master assets live in Amazon S3, and metadata and viewing history are stored in per-region RDS/DynamoDB. Recent tightening of regional regulation and steep traffic growth have pushed the current design to its limits across regulation, latency, cost, and permission management.","The dominant constraint is data residency. Personal data tied to EU subscribers (names, payment details, viewing history) must be stored within an EU Region, and auditors require that the encryption keys also be managed and revocable within the EU. Brazil's LGPD and India's data-protection rules likewise restrict cross-border movement of regulated data. Master video assets themselves contain no personal data, so the delivery team wants to consolidate them centrally for cost efficiency. Legal, however, insists that regulated and non-regulated data be structurally separated in the architecture, arguing that cross-region copies make audits hard to justify.","Non-functional requirements are strict. Consumer playback start latency (TTFB) must stay within p95 400 ms per region, and live-stream availability is committed to customers at a 99.95% SLA. For the B2B SaaS, some tenants contract for a private, non-Internet path to the management console and upload API, and auditors have flagged the current public-endpoint access. A recent penetration test also found that the S3 origin bucket is directly reachable from outside CloudFront, and that some IAM roles grant `s3:*` or `kms:*` on broad resources.","Origin load is another problem. CloudFront's cache hit ratio averages only 78% across regions, with heavy origin round-trips for B2B dynamic thumbnail generation and manifest delivery. At peak, requests concentrate on S3 and the backing Lambda@Edge / origin services, hitting both origin scaling limits and S3 egress costs. In some cases other regions fetch directly from the North American origin, which is inefficient for latency and cost and undesirable for regional data boundaries.","Permission management is worse still. Development, operations, and data-analytics teams all work inside a single AWS account, and analytics IAM users hold broad permissions on production encryption keys and master buckets. The tenant-operations automation role is granted read/write on the entire bucket when it only ever needs its own tenant prefix. Security has made least privilege, tag-based permission separation (ABAC), and a structural block against privilege escalation mandatory conditions for the redesign.","On cost, CloudFront's price class is set to all edge locations even though 96% of real traffic concentrates in the five regions above. S3 uses S3 Standard in every Region, and master assets untouched for 90+ days make up 62% of total volume. RDS is Multi-AZ, but heavy analytics queries share the same instance as production transactions, hurting both cost and performance. The CFO has set a corporate goal to cut monthly infrastructure cost by 25% without compromising regulation or SLA at all.","Priorities collide in the steering committee. Delivery wants low latency and a simple consolidated design, Legal and Security want strict regional isolation and least privilege, and Finance wants cost cuts. As lead solutions architect you must fuse these conflicting demands into one reference architecture, making design calls in each area that break no requirement decisively. In the questions below, cross-reference the tables to pick the single option that simultaneously satisfies the residency, latency, permission, and cost constraints."]},"tables":[{"title":{"ja":"表1: 地域別の規制・保管要件と非機能SLO","en":"Table 1: Per-Region Regulatory / Residency Requirements and Non-Functional SLOs"},"headers":{"ja":["地域(リージョン)","適用規制","規制対象データの保管制約","鍵管理要件","TTFB p95 目標","可用性SLA"],"en":["Region","Regulation","Residency constraint for regulated data","Key management requirement","TTFB p95 target","Availability SLA"]},"rows":{"ja":[["EU (eu-central-1)","GDPR","EU域内のみ・国外複製不可","EU内で管理・失効可能","400 ms","99.95%"],["日本 (ap-northeast-1)","APPI","越境は同意ベース・原則国内","国内管理を推奨","350 ms","99.95%"],["ブラジル (sa-east-1)","LGPD","国外移転を制限","国内管理を推奨","450 ms","99.9%"],["インド (ap-south-1)","DPDP","重要個人データは国内保管","国内管理を推奨","450 ms","99.9%"],["北米 (us-east-1)","州法(CCPA等)","地域内推奨・法規制は緩い","地域内管理","300 ms","99.95%"]],"en":[["EU (eu-central-1)","GDPR","EU only; no cross-border copies","Managed/revocable in EU","400 ms","99.95%"],["Japan (ap-northeast-1)","APPI","Cross-border by consent; domestic preferred","Domestic management recommended","350 ms","99.95%"],["Brazil (sa-east-1)","LGPD","Restricts overseas transfer","Domestic management recommended","450 ms","99.9%"],["India (ap-south-1)","DPDP","Sensitive personal data kept in-country","Domestic management recommended","450 ms","99.9%"],["North America (us-east-1)","State laws (CCPA etc.)","In-region preferred; looser rules","In-region management","300 ms","99.95%"]]}},{"title":{"ja":"表2: 現行構成コンポーネントと課題","en":"Table 2: Current Architecture Components and Issues"},"headers":{"ja":["コンポーネント","現行の実装","検出された課題"],"en":["Component","Current implementation","Detected issue"]},"rows":{"ja":[["配信","CloudFront(料金クラス:全世界)","実需要は5地域に96%集中しコスト過大"],["原本ストレージ","各リージョン S3 Standard","90日超未アクセスが総容量の62%"],["オリジン保護","S3バケットポリシーで一部IP許可","CloudFront以外から直接到達可能"],["メタデータ/履歴","地域別 RDS(分析と相乗り)","重いクエリが本番性能とコストを圧迫"],["法人接続","パブリックHTTPSエンドポイント","専用経路契約テナントの監査指摘"]],"en":[["Delivery","CloudFront (price class: all locations)","96% of demand in 5 regions; over-cost"],["Master storage","S3 Standard in each Region","62% of volume untouched for 90+ days"],["Origin protection","Some IPs allowed via bucket policy","Directly reachable from outside CloudFront"],["Metadata/history","Per-region RDS (shared with analytics)","Heavy queries hurt prod cost and speed"],["B2B connectivity","Public HTTPS endpoint","Audit flag for private-path tenants"]]}},{"title":{"ja":"表3: 地域別トラフィックとオリジン負荷(ピーク時)","en":"Table 3: Per-Region Traffic and Origin Load (at Peak)"},"headers":{"ja":["地域","ピークreq/s","キャッシュヒット率","月間オリジンegress","現状TTFB p95"],"en":["Region","Peak req/s","Cache hit ratio","Monthly origin egress","Current TTFB p95"]},"rows":{"ja":[["EU","38,000","76%","210 TB","520 ms"],["日本","22,000","81%","95 TB","410 ms"],["ブラジル","12,000","72%","140 TB","610 ms"],["インド","18,000","70%","160 TB","640 ms"],["北米","44,000","83%","180 TB","300 ms"]],"en":[["EU","38,000","76%","210 TB","520 ms"],["Japan","22,000","81%","95 TB","410 ms"],["Brazil","12,000","72%","140 TB","610 ms"],["India","18,000","70%","160 TB","640 ms"],["North America","44,000","83%","180 TB","300 ms"]]}},{"title":{"ja":"表4: セキュリティ・権限の現状とリスク","en":"Table 4: Current Security / Permission State and Risk"},"headers":{"ja":["対象","現状の権限/設定","リスク"],"en":["Subject","Current permission/config","Risk"]},"rows":{"ja":[["分析チーム","本番KMS鍵と原本に広域権限","越権アクセスと鍵誤用の恐れ"],["テナント自動化ロール","バケット全体に読み書き","他テナントデータへの越境参照"],["管理者ロール","iam:* とパスロール許可","権限昇格の経路が存在"],["暗号鍵","単一リージョンKMS・共有","EU鍵の域内失効要件を未充足"],["監査ログ","一部アカウントのみCloudTrail","横断的な追跡が不完全"]],"en":[["Analytics team","Broad rights on prod KMS keys/masters","Over-access and key misuse risk"],["Tenant automation role","Read/write on entire bucket","Cross-tenant data access"],["Admin role","iam:* and PassRole allowed","Privilege-escalation path exists"],["Encryption keys","Single-region KMS, shared","EU in-region revocation unmet"],["Audit logs","CloudTrail in some accounts only","Incomplete cross-account tracing"]]}},{"title":{"ja":"表5: コスト内訳と主な最適化選択肢の比較","en":"Table 5: Cost Breakdown and Comparison of Key Optimization Options"},"headers":{"ja":["項目","現状月額(概算)","最適化案","見込み効果"],"en":["Item","Current monthly (approx.)","Optimization option","Expected effect"]},"rows":{"ja":[["CloudFront配信","$180,000","料金クラスを主要地域に限定","配信費 約12%減"],["S3ストレージ","$140,000","ライフサイクルでGlacier IRへ移行","保管費 約18%減"],["オリジンegress","$90,000","キャッシュ最適化でヒット率向上","転送費 約20%減"],["RDS","$120,000","分析をリードレプリカ/別基盤へ分離","本番費 約15%減"],["監視/その他","$40,000","統合と保持期間見直し","約8%減"]],"en":[["CloudFront delivery","$180,000","Limit price class to key regions","~12% delivery cut"],["S3 storage","$140,000","Lifecycle to Glacier IR","~18% storage cut"],["Origin egress","$90,000","Cache tuning to lift hit ratio","~20% transfer cut"],["RDS","$120,000","Split analytics to read replica/other","~15% prod cut"],["Monitoring/other","$40,000","Consolidate and revise retention","~8% cut"]]}}],"questions":[{"n":1,"q":{"ja":"表1と表2を踏まえ、EU契約者の個人データと映像マスターの保管方針として、規制・法務要件を破らずコスト効率も考慮した設計はどれか。","en":"Given Tables 1 and 2, which storage design for EU subscriber personal data and video masters honors the regulatory/legal requirements while also being cost-conscious?"},"options":[{"label":{"ja":"個人データはEUリージョン内に保管し、個人データを含まないマスターのみ共有リージョンへ集約する","en":"Keep personal data in EU Region S3/DB, and consolidate non-personal masters in a shared Region, separating the boundary"},"ok":true,"exp":{"ja":"規制対象(個人データ)はEU域内に留め、非規制のマスターのみ集約するため、レジデンシを満たしつつコスト効率と法務が求める境界分離の双方を達成する。","en":"Regulated personal data stays in the EU while only non-regulated masters are consolidated, satisfying residency plus both cost efficiency and the boundary separation Legal wants."}},{"label":{"ja":"運用簡素化のため個人データとマスターをすべて北米リージョンに集約し、CloudFrontで各地域へ配信する","en":"For simplicity, consolidate all personal data and masters in North America and deliver to each region via CloudFront"},"ok":false,"exp":{"ja":"EU契約者の個人データを国外(北米)に置く時点でGDPRの域内保管要件に決定的に反する。配信の話とレジデンシは別問題であり誤り。","en":"Placing EU personal data outside the EU decisively violates GDPR residency; delivery via CloudFront does not address where regulated data resides."}},{"label":{"ja":"個人データもマスターも各地域リージョンに完全複製し、どこからでも同一データを参照できるようにする","en":"Fully replicate both personal data and masters into every Region so identical data is reachable anywhere"},"ok":false,"exp":{"ja":"個人データを全地域へ複製すると越境保管が発生しGDPR/LGPD等に反する。法務が嫌う『地域跨ぎの複製』にも該当しコスト増でもある。","en":"Replicating personal data everywhere causes cross-border storage that breaks GDPR/LGPD, is exactly the cross-region copy Legal opposes, and raises cost."}},{"label":{"ja":"個人データをEUに残す一方、マスターはCloudFrontのエッジキャッシュのみに保持しオリジンストレージを廃止する","en":"Keep personal data in the EU but hold masters only in CloudFront edge cache and drop origin storage"},"ok":false,"exp":{"ja":"エッジキャッシュは一時的でありオリジンの永続保管を代替できない。TTLで消えれば原本が失われるため、可用性・耐久性の観点で成立しない。","en":"Edge cache is ephemeral and cannot replace durable origin storage; once TTL expires the master is gone, so it fails on durability and availability."}}]},{"n":2,"q":{"ja":"表2と表4より、S3オリジンがCloudFront以外から直接到達できる問題を、最小権限で解消する最も適切な方法はどれか。","en":"From Tables 2 and 4, what is the most appropriate least-privilege way to stop the S3 origin from being reachable outside CloudFront?"},"options":[{"label":{"ja":"Origin Access Control(OAC)を有効化し、当該ディストリビューションのみ許可する","en":"Enable Origin Access Control (OAC) and scope the bucket policy to allow only that distribution"},"ok":true,"exp":{"ja":"OACはSigV4でCloudFront経由アクセスに限定でき、バケットをパブリック非公開のまま特定ディストリビューションのみ許可する現行のベストプラクティス。","en":"OAC restricts access to CloudFront via SigV4 and, with a distribution-scoped bucket policy, keeps the bucket private — the current best practice."}},{"label":{"ja":"バケットポリシーで既知のCloudFrontエッジIP範囲のみを許可し、その他の送信元IPをすべて拒否する","en":"Allow only known CloudFront edge IP ranges in the bucket policy and deny all other source IPs"},"ok":false,"exp":{"ja":"エッジIPは動的に変化し維持不能で、なりすましにも弱い。OAC/OAIという専用機構がある以上IP列挙は脆弱で誤り。","en":"Edge IP ranges change dynamically and are unmaintainable and spoofable; with OAC/OAI available, IP allow-listing is fragile and wrong."}},{"label":{"ja":"バケットを非公開のままにし、視聴者へは有効期限付きのS3署名付きURLを直接発行して配信する","en":"Keep the bucket private and deliver by issuing time-limited S3 presigned URLs directly to viewers"},"ok":false,"exp":{"ja":"署名付きURLはオリジンへ直接アクセスさせCloudFrontのキャッシュ/低レイテンシを迂回する。ヒット率やegress課題を悪化させ要件に反する。","en":"Presigned URLs send viewers straight to the origin, bypassing CloudFront caching and low latency, worsening hit ratio and egress against requirements."}},{"label":{"ja":"S3のブロックパブリックアクセスを無効化し、静的ウェブサイトホスティングを有効にして公開配信する","en":"Disable S3 Block Public Access and turn on static website hosting to serve publicly"},"ok":false,"exp":{"ja":"バケットを公開する方向であり、直接到達を止めるどころか広げる。最小権限とオリジン保護の要件に真っ向から反する。","en":"This makes the bucket public — widening direct reach rather than stopping it — directly contradicting least privilege and origin protection."}}]},{"n":3,"q":{"ja":"表4のテナント自動化ロールについて、各テナントが自分のプレフィックスのみ操作できるよう権限分離する、最も拡張性の高い方式はどれか。","en":"For the tenant automation role in Table 4, which is the most scalable way to separate permissions so each tenant can operate only its own prefix?"},"options":[{"label":{"ja":"リクエスト内のタグとリソースタグの一致を条件にABACを用い、単一ロールで自テナントのみ許可する","en":"Use ABAC keyed on matching request and resource tags so a single role permits only the tenant's own scope"},"ok":true,"exp":{"ja":"ABACはタグ一致条件で自テナント範囲に限定でき、テナント増加時もポリシー数を増やさず拡張できる。最小権限と運用効率を両立する。","en":"ABAC limits access to the tenant's own scope via tag-match conditions and scales without adding policies as tenants grow — least privilege plus efficiency."}},{"label":{"ja":"テナントごとに専用IAMロールと固有バケットポリシーを個別作成し、追加のたびに新規ロールを発行する","en":"Create a dedicated IAM role and unique bucket policy per tenant, issuing a new role on every addition"},"ok":false,"exp":{"ja":"分離自体は可能だが1,800テナント規模ではロール数が爆発し管理不能。拡張性の観点で最適でなくABACに劣る。","en":"It does separate access but role count explodes at 1,800 tenants and becomes unmanageable; it is not scalable and is inferior to ABAC."}},{"label":{"ja":"全テナント共通の広い権限を維持し、アプリ層のコードで対象プレフィックスの検証を実装する","en":"Keep one broad shared permission and enforce prefix checks in application-layer code"},"ok":false,"exp":{"ja":"IAM上は越権のままでアプリのバグや迂回で他テナントに到達し得る。構造的な最小権限を求める要件に反する。","en":"IAM stays over-privileged, so an app bug or bypass can reach other tenants; it fails the requirement for structural least privilege."}},{"label":{"ja":"テナントごとに個別のAWSアカウントを作成し、アカウント境界だけで完全にデータを分離する","en":"Create a separate AWS account per tenant and isolate data solely by account boundary"},"ok":false,"exp":{"ja":"強い分離だが1,800アカウントの運用は過剰で、共有配信基盤とも整合しない。ここで求める単一基盤内の権限分離には不適。","en":"Strong isolation, but 1,800 accounts is excessive and misaligned with the shared delivery platform — unsuitable for in-platform permission separation here."}}]},{"n":4,"q":{"ja":"表1と表4より、EUの鍵管理要件(域内で管理・失効可能)と全社的な暗号運用を両立させる設計として最適なものはどれか。","en":"From Tables 1 and 4, which design best reconciles the EU key requirement (in-region management/revocation) with company-wide encryption operations?"},"options":[{"label":{"ja":"各地域のKMSカスタマー管理キーで暗号化し、鍵ポリシーで用途別プリンシパルに利用を限定する","en":"Encrypt with per-region KMS customer managed keys and scope usage to purpose-specific principals via key policy"},"ok":true,"exp":{"ja":"地域別のCMKなら鍵はリージョン内に留まり域内失効も可能で、鍵ポリシーで分析等の越権も遮断できる。レジデンシと最小権限を同時に満たす。","en":"Per-region CMKs keep keys in-region with in-region revocation, and key policies block over-access such as analytics — meeting residency and least privilege together."}},{"label":{"ja":"単一のKMSマルチリージョンキーを全地域へ複製し、鍵管理を一元化して運用負荷を下げる","en":"Replicate one KMS multi-Region key to all regions to centralize key management and cut ops load"},"ok":false,"exp":{"ja":"マルチリージョンキーはレプリカが他地域に存在し、EUが求める『域内のみで管理・失効』を厳密には満たさない。監査説明で不利になる。","en":"A multi-Region key places replicas elsewhere, not strictly meeting the EU's in-region-only management/revocation and weakening the audit story."}},{"label":{"ja":"S3のAmazon管理キー(SSE-S3)を全リージョンで用い、鍵管理をAWSに完全委任する","en":"Use Amazon-managed keys (SSE-S3) in every Region and fully delegate key management to AWS"},"ok":false,"exp":{"ja":"SSE-S3では顧客が鍵ポリシーや失効を制御できず、EUの域内失効要件と権限分離を満たせない。監査要件に不足。","en":"SSE-S3 gives the customer no control over key policy or revocation, failing the EU in-region revocation and permission-separation requirements."}},{"label":{"ja":"アプリ側で独自実装した共通鍵をコード内に保持し、全リージョンで同一鍵を使い回して暗号化する","en":"Hold a self-implemented shared key in application code and reuse the same key across all regions"},"ok":false,"exp":{"ja":"鍵のハードコードと使い回しは重大なアンチパターンで、域内管理も失効も監査も成立しない。規制・セキュリティ双方に反する。","en":"Hardcoding and reusing a key is a severe anti-pattern with no in-region management, revocation, or audit — violating both regulation and security."}}]},{"n":5,"q":{"ja":"表2の法人SaaS接続について、専用経路契約テナントに『インターネットを経由しない接続』を提供する最適な方法はどれか。","en":"For the B2B SaaS connectivity in Table 2, what is the best way to give private-path tenants a connection that does not traverse the Internet?"},"options":[{"label":{"ja":"SaaSの管理APIをAWS PrivateLinkで公開しテナントVPCから接続させる","en":"Front the SaaS management API with an NLB and expose it via AWS PrivateLink for tenant VPC endpoint access"},"ok":true,"exp":{"ja":"PrivateLink(VPCエンドポイントサービス)はトラフィックをAWS内部に閉じ、インターネットを経由しない接続を実現する。専用経路要件に最も適合する。","en":"PrivateLink (endpoint service) keeps traffic inside the AWS network with no Internet path, best matching the private-connectivity requirement."}},{"label":{"ja":"パブリックエンドポイントは維持しつつ、WAFとIP許可リストでテナントのグローバルIPのみ通す","en":"Keep the public endpoint but use WAF and an IP allow-list to permit only tenants' global IPs"},"ok":false,"exp":{"ja":"経路自体はインターネットのままで『非インターネット接続』の契約要件を満たさない。IP許可は保護であって専用経路ではない。","en":"The path remains the public Internet, failing the non-Internet contract; IP allow-listing is protection, not a private path."}},{"label":{"ja":"テナントごとにサイト間VPNを構築し、暗号化トンネルでSaaS管理コンソールへ到達させる","en":"Establish a site-to-site VPN per tenant to reach the SaaS console over an encrypted tunnel"},"ok":false,"exp":{"ja":"VPNはインターネット上の暗号トンネルであり物理的にはインターネット経由。多数テナントで運用も重く、PrivateLinkが本要件に上位。","en":"A VPN is an encrypted tunnel over the Internet, so it still traverses it, and is operationally heavy at scale — PrivateLink is superior here."}},{"label":{"ja":"CloudFront経由でAPIを配信し、署名付きCookieでテナント認証を行い接続を保護する","en":"Serve the API through CloudFront and protect access with signed cookies for tenant auth"},"ok":false,"exp":{"ja":"CloudFrontはインターネット向けの配信であり専用経路にはならない。認証強化はできても『非インターネット』要件は満たせない。","en":"CloudFront is Internet-facing delivery, not a private path; it can strengthen auth but cannot meet the non-Internet requirement."}}]},{"n":6,"q":{"ja":"表3と表5を横断し、SLAと規制を守りつつ月間コスト25%削減に最も寄与する組み合わせはどれか。","en":"Cross-referencing Tables 3 and 5, which combination best drives a 25% monthly cost cut while preserving SLA and regulation?"},"options":[{"label":{"ja":"料金クラスを主要地域に絞り、古い原本をGlacier IRへ移し、キャッシュ最適化と分析分離を併用する","en":"Narrow the price class to key regions, tier old masters to Glacier IR, and add cache tuning with analytics split"},"ok":true,"exp":{"ja":"配信・保管・転送・RDSの各領域で効果を積み上げ、可用性やレジデンシを損なわず合計で25%削減に届く。表5の効果が整合する最適解。","en":"It stacks savings across delivery, storage, transfer, and RDS without harming availability or residency, reaching 25% consistent with Table 5 — the best fit."}},{"label":{"ja":"アクセス頻度の高い配信中コンテンツも含め全原本を即座にGlacier Deep Archiveへ移行する","en":"Move all masters, including hot in-delivery content, immediately to Glacier Deep Archive"},"ok":false,"exp":{"ja":"Deep Archiveは取り出しに数時間かかり、配信中コンテンツに使うとTTFBやSLAを破綻させる。ホットデータへの適用は誤り。","en":"Deep Archive needs hours to retrieve; applying it to hot delivery content breaks TTFB and SLA — wrong for active data."}},{"label":{"ja":"可用性SLAを99.95%から99.5%へ緩和し、マルチAZを停止してRDSを単一AZ化する","en":"Relax the SLA from 99.95% to 99.5% and disable Multi-AZ to run RDS single-AZ"},"ok":false,"exp":{"ja":"コストは下がるが顧客約束のSLAを引き下げており『SLAを妥協しない』前提に反する。可用性低下も招き不適。","en":"It cuts cost but lowers the committed SLA, violating the 'no SLA compromise' premise and reducing availability — unacceptable."}},{"label":{"ja":"全リージョンのS3をStandardのまま残し、CloudFrontのTTLをゼロにして常に最新を返す","en":"Keep all Regions on S3 Standard and set CloudFront TTL to zero to always serve fresh"},"ok":false,"exp":{"ja":"TTLゼロはキャッシュを実質無効化しヒット率とegressを悪化させ、コストを増やす。削減目標に真逆で誤り。","en":"Zero TTL effectively disables caching, hurting hit ratio and egress and raising cost — the opposite of the savings goal."}}]}]}];

// ExamCaseRunner — 本試験形式のケース（複数ケース選択＋共有ケース本文＋資料表＋僅差4択＋根拠解説）
function ExamCaseRunner({ cases, lang, onBack, backRef, ck }) {
  const caseDone = useDoneSet("case:" + (ck || "x"));
  const g = (o) => (o && (o[lang] != null ? o[lang] : o.ja));
  const clist = Array.isArray(cases) ? cases : [cases];
  const [pick, setPick] = useState(clist.length === 1 ? 0 : null);
  const [qi, setQi] = useState(0);
  const [answers, setAnswers] = useState({});
  const [finished, setFinished] = useState(false);

  const th = { textAlign: "left", padding: "7px 9px", background: "#EDE9E0", color: C.deep, fontSize: 11.5, fontWeight: 700, borderBottom: `1px solid ${C.mid}`, whiteSpace: "nowrap" };
  const td = { padding: "7px 9px", fontSize: 12, borderBottom: `1px solid ${C.mid}`, verticalAlign: "top", lineHeight: 1.45 };

  const openCase = (i) => { setPick(i); setQi(0); setAnswers({}); setFinished(false); };
  useEffect(() => { if (!backRef) return; backRef.current = () => { if (pick !== null && clist.length > 1) { setPick(null); setQi(0); setAnswers({}); setFinished(false); return true; } return false; }; return () => { if (backRef) backRef.current = null; }; }, [pick, backRef]);
  const backToList = () => { if (clist.length > 1) { setPick(null); setQi(0); setAnswers({}); setFinished(false); } else onBack(); };

  if (pick === null) {
    return (
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <button onClick={onBack} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{lang === "ja" ? "← 戻る" : "← Back"}</button>
        </div>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 4 }}>{lang === "ja" ? "本試験形式ケース" : "Exam-style cases"}</div>
        <div style={{ fontSize: 12, color: "#5d6c83", marginBottom: 12 }}>{lang === "ja" ? "資料表つき・僅差4択・全選択肢に根拠解説" : "Data tables, 4 close options, rationale for each"}</div>
        {clist.map((c, i) => (
          <button key={i} onClick={() => openCase(i)}
            style={{ width: "100%", textAlign: "left", padding: "14px 15px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontWeight: 700, fontSize: 13.5, color: C.deep, lineHeight: 1.45, paddingRight: 10 }}><DoneCheck on={caseDone.has(i)} onToggle={(e) => caseDone.toggle(i, e)} />{g(c.title)}</span>
            <span style={{ fontSize: 11.5, color: "#5d6c83", whiteSpace: "nowrap" }}>{c.questions.length}{lang === "ja" ? "問" : "Q"}</span>
          </button>
        ))}
      </div>
    );
  }

  const data = clist[pick];
  const qs = data.questions;
  const Q = qs[qi];
  const sel = answers[qi] != null ? answers[qi] : null;
  const choose = (i) => { if (sel !== null) return; setAnswers(a => ({ ...a, [qi]: i })); };
  const prev = () => { if (qi > 0) setQi(qi - 1); };
  const next = () => { if (qi < qs.length - 1) setQi(qi + 1); };
  const restart = () => { setQi(0); setAnswers({}); setFinished(false); };

  let correct = 0;
  for (let k = 0; k < qs.length; k++) { const a = answers[k]; if (a != null && qs[k].options[a] && qs[k].options[a].ok) correct++; }
  const answeredCount = Object.keys(answers).length;
  const rate = qs.length ? Math.round((correct / qs.length) * 100) : 0;

  const navBtn = (label, onClick, enabled, primary) => (
    <button onClick={enabled ? onClick : undefined} disabled={!enabled}
      style={{ flex: 1, padding: "11px 12px", borderRadius: 9, fontSize: 13.5, fontWeight: 700,
        cursor: enabled ? "pointer" : "default",
        border: primary ? "none" : `1.5px solid ${enabled ? C.primary : C.mid}`,
        background: primary ? (enabled ? C.primary : C.mid) : "#fff",
        color: primary ? nvInk("#ffffff", enabled ? C.primary : C.mid) : (enabled ? nvInk(C.primary, "#ffffff") : nvInk("#b9c4d6", "#ffffff", 3)) }}>{label}</button>
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={backToList} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{clist.length > 1 ? (lang === "ja" ? "← ケース一覧" : "← Case list") : (lang === "ja" ? "← 戻る" : "← Back")}</button>
        {!finished && <span style={{ fontSize: 12, color: "#5d6c83" }}>{lang === "ja" ? `問 ${qi + 1} / ${qs.length}` : `Q ${qi + 1} / ${qs.length}`}</span>}
      </div>

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginBottom: 12 }}>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 10 }}>{g(data.title)}</div>
        <div style={{ fontSize: 11, fontWeight: 700, color: nvInk(C.primary, "#ffffff"), marginBottom: 6 }}>{lang === "ja" ? "ケース本文（資料）" : "Case (materials)"}</div>
        {g(data.body).map((p, i) => (<div key={i} style={{ fontSize: 13, lineHeight: 1.7, marginBottom: 8, color: C.ink }}>{p}</div>))}
        {(data.tables || []).map((tb, ti) => (
          <div key={ti} style={{ marginTop: 12 }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: C.deep, marginBottom: 5 }}>{g(tb.title)}</div>
            <div style={{ overflowX: "auto", border: `1px solid ${C.mid}`, borderRadius: 8 }}>
              <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 320 }}>
                <thead><tr>{g(tb.headers).map((h, hi) => (<th key={hi} style={th}>{h}</th>))}</tr></thead>
                <tbody>{g(tb.rows).map((r, ri) => (<tr key={ri}>{r.map((cell, ci) => (<td key={ci} style={td}>{cell}</td>))}</tr>))}</tbody>
              </table>
            </div>
          </div>
        ))}
      </div>

      {finished ? (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ textAlign: "center", marginBottom: 12 }}>
            <div style={{ fontSize: 13, color: "#5a6a85", fontWeight: 600, marginBottom: 6 }}>{lang === "ja" ? "ケース完了" : "Case complete"}</div>
            <div style={{ fontSize: 32, fontWeight: 800, color: rate >= PASS ? C.ok : C.ng }}>{rate}%</div>
            <div style={{ fontSize: 12.5, color: "#5d6c83", marginTop: 2 }}>{lang === "ja" ? `正解 ${correct} / ${qs.length} 問` : `${correct} / ${qs.length} correct`}</div>
          </div>
          <Bar pct={rate} color={rate >= PASS ? C.ok : C.ng} />
          <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
            <button onClick={() => { setFinished(false); setQi(0); }} style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: nvInk(C.primary, "#ffffff"), fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "解答を見直す" : "Review answers"}</button>
            <button onClick={restart} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary, 3), fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "もう一度" : "Retry"}</button>
          </div>
        </div>
      ) : (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ fontSize: 14.5, fontWeight: 700, marginBottom: 12, color: C.deep }}>{lang === "ja" ? `問${Q.n}. ` : `Q${Q.n}. `}{g(Q.q)}</div>
          {Q.options.map((opt, i) => {
            let bg = "#fff", bd = C.mid, col = C.ink;
            if (sel !== null) { if (opt.ok) { bg = "#E6F4EC"; bd = C.ok; col = C.ok; } else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; } }
            return (
              <button key={i} onClick={() => choose(i)} disabled={sel !== null}
                style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel === null ? "pointer" : "default", fontSize: 13.5, lineHeight: 1.5, fontWeight: sel !== null && opt.ok ? 700 : 500 }}>
                <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && opt.ok ? "✓" : sel !== null && i === sel ? "✗" : "ABCD"[i]}</span>{g(opt.label)}
              </button>
            );
          })}
          {sel !== null && (
            <div style={{ marginTop: 12 }}>
              {Q.options.map((opt, i) => (
                <div key={i} style={{ background: opt.ok ? "#E6F4EC" : (i === sel ? "#FBEAE8" : C.light), borderRadius: 8, padding: "9px 11px", marginBottom: 6, fontSize: 12.5, lineHeight: 1.55 }}>
                  <span style={{ fontWeight: 700, marginRight: 6, color: opt.ok ? C.ok : (i === sel ? C.ng : "#5d6c83") }}>{"ABCD"[i]}{opt.ok ? (lang === "ja" ? "（正解）" : " (correct)") : ""}</span>{g(opt.exp)}
                </div>
              ))}
            </div>
          )}
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            {navBtn(lang === "ja" ? "← 前の問題" : "← Previous", prev, qi > 0, false)}
            {qi < qs.length - 1
              ? navBtn(lang === "ja" ? "次の問題 →" : "Next →", next, sel !== null, true)
              : navBtn(lang === "ja" ? "結果を見る →" : "See result →", () => setFinished(true), answeredCount === qs.length, true)}
          </div>
        </div>
      )}
    </div>
  );
}

function Exam({ onAnswer, onWrong, lang, t }) {
  const en = lang === "en";
  const [mode, setMode] = useState("normal");
  const [examMode, setExamMode] = useState("practice");
  const [setNo, setSetNo] = useState(null);
  const [domKey, setDomKey] = useState(null);
  const [phase, setPhase] = useState("select");
  const [pos, setPos] = useState(0);
  const [picks, setPicks] = useState({});
  const [flags, setFlags] = useState({});
  const [timeLeft, setTimeLeft] = useState(130 * 60);
  const [qs, setQs] = useState([]);
  const [title, setTitle] = useState("");
  const [revealed, setRevealed] = useState({});
  const [showExam, setShowExam] = useState(false);

  const isPractice = examMode === "practice";

  const score = () => {
    qs.forEach((Q, i) => {
      const pick = picks[i] || [];
      const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
      const ok = arrEq(pick, correctAns);
      onAnswer(Q.d, ok);
      if (!ok && onWrong) onWrong(Q);
    });
    setPhase("result");
  };

  useEffect(() => {
    if (phase !== "run" || isPractice) return;
    if (timeLeft <= 0) { score(); return; }
    const id = setInterval(() => setTimeLeft(tl => tl - 1), 1000);
    return () => clearInterval(id);
  }, [phase, timeLeft, isPractice]);

  const begin = (questions, label) => {
    setQs(questions); setTitle(label); setPos(0); setPicks({}); setFlags({}); setRevealed({}); setTimeLeft(130 * 60); setPhase("run");
  };
  const startNormal = (n) => { setSetNo(n); begin(EXAM_SETS[n], `${t.setLabel} ${n}`); };
  const startDomain = (id) => { setDomKey(id); begin(buildDomainSet(id), domName(id, lang)); };
  const restart = () => { if (mode === "normal") startNormal(setNo); else startDomain(domKey); };

  const togglePick = (qi, optIdx, multi) => {
    if (isPractice && revealed[qi]) return;
    setPicks(p => {
      const cur = p[qi] || [];
      if (multi) { const has = cur.includes(optIdx); return { ...p, [qi]: has ? cur.filter(x => x !== optIdx) : [...cur, optIdx] }; }
      return { ...p, [qi]: [optIdx] };
    });
  };

  const revealPractice = (qi) => {
    const Q = qs[qi];
    const pick = picks[qi] || [];
    const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
    const ok = arrEq(pick, correctAns);
    onAnswer(Q.d, ok);
    if (!ok && onWrong) onWrong(Q);
    setRevealed(r => ({ ...r, [qi]: true }));
  };

  const fmtTime = (s) => `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

  if (showExam) return <ExamCaseRunner ck="SAA_EXAM_CASES" cases={SAA_EXAM_CASES} lang={lang} onBack={() => setShowExam(false)} />;

  if (phase === "select") {
    const modeBtns = [
      ["normal", en ? "Standard sets" : "通常セット"],
      ["domain", en ? "Domain focus" : "ドメイン重点版"],
    ];
    const examModeBtns = [
      ["practice", t.examModePractice],
      ["real", t.examModeReal],
    ];
    return (
      <div>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 8 }}>
          <div style={{ display: "inline-flex", background: C.light, borderRadius: 22, padding: 4 }}>
            {examModeBtns.map(([k, label]) => (
              <button key={k} onClick={() => setExamMode(k)}
                style={{ border: "none", cursor: "pointer", borderRadius: 18, padding: "9px 22px", fontSize: 13, fontWeight: 700,
                  background: examMode === k ? "#fff" : "transparent", color: examMode === k ? nvInk(C.deep, "#ffffff") : nvInk("#7b6d62", C.mid),
                  boxShadow: examMode === k ? "0 1px 4px rgba(0,0,0,.12)" : "none" }}>
                {label}
              </button>
            ))}
          </div>
        </div>
        <div style={{ textAlign: "center", fontSize: 12, color: "#7b6d62", marginBottom: 16, lineHeight: 1.5, padding: "0 10px" }}>
          {isPractice ? t.examModePracticeDesc : t.examModeRealDesc}
        </div>

        <div style={{ display: "flex", gap: 6, marginBottom: 14, flexWrap: "wrap" }}>
          {modeBtns.map(([k, label]) => (
            <button key={k} onClick={() => setMode(k)}
              style={{ flex: "1 1 45%", padding: "10px 8px", borderRadius: 10, cursor: "pointer", fontSize: 12.5, fontWeight: 700,
                border: `1.5px solid ${mode === k ? C.primary : C.mid}`, background: mode === k ? C.primary : "#fff", color: mode === k ? C.deep : nvInk(C.ink, "#ffffff") }}>
              {label}
            </button>
          ))}
        </div>
        {mode === "normal" && (
          <>
            <Card title={t.examTitle}><div style={{ fontSize: 13, lineHeight: 1.6, color: "#5a4d43" }}>{t.examDesc}</div></Card>
            <button onClick={() => setShowExam(true)}
              style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
                border: `1.5px solid ${C.deep}`, background: "#FBF7EF", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span>
                <span style={{ fontWeight: 700, fontSize: 15, color: C.deep }}>{en ? "Exam-style case" : "本試験形式ケース"}</span>
                <span style={{ fontSize: 12, color: "#7b6d62", marginLeft: 8 }}>{en ? "Design scenario with data tables & rationale" : "設計シナリオ・資料表つき・僅差4択・根拠解説"}</span>
              </span>
              <span style={{ fontSize: 12.5, fontWeight: 700, color: nvInk(C.primary, "#ffffff") }}>{en ? "Start →" : "挑戦 →"}</span>
            </button>
            {EXAM_SET_NOS.map(n => (
              <button key={n} onClick={() => startNormal(n)}
                style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
                  border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontWeight: 700, fontSize: 15, color: C.deep }}>{t.setLabel} {n}</span>
                <span style={{ fontSize: 12.5, fontWeight: 700, color: nvInk(C.primary, "#ffffff") }}>{t.start}</span>
              </button>
            ))}
          </>
        )}
        {mode === "domain" && DOMAINS.map(d => (
          <button key={d.id} onClick={() => startDomain(d.id)}
            style={{ width: "100%", textAlign: "left", padding: "15px 16px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span>
              <span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "2px 7px", fontSize: 11, marginRight: 8, fontWeight: 700 }}>{d.id}</span>
              <span style={{ fontWeight: 700, fontSize: 14, color: C.deep }}>{domName(d.id, lang)}</span>
            </span>
            <span style={{ fontSize: 12.5, fontWeight: 700, color: nvInk(C.primary, "#ffffff") }}>{t.start}</span>
          </button>
        ))}
      </div>
    );
  }

  if (phase === "result") {
    let c = 0;
    const wrong = [];
    qs.forEach((Q, i) => {
      const pick = picks[i] || [];
      const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
      if (arrEq(pick, correctAns)) c++; else wrong.push({ Q, pick, correctAns });
    });
    const rate = Math.round((c / qs.length) * 100);
    const passed = rate >= PASS;
    return (
      <div>
        <div style={{ background: passed ? "#E8F5EE" : "#FBEAE8", border: `2px solid ${passed ? C.ok : C.ng}`, borderRadius: 12, padding: 18, textAlign: "center", marginBottom: 14 }}>
          <div style={{ fontSize: 13, color: "#6b5d52" }}>{title} {t.result}</div>
          <div style={{ fontSize: 40, fontWeight: 800, color: nvInk(passed ? C.ok : C.ng, passed ? "#E4F6EC" : "#FBE9E7", 3) }}>{rate}%</div>
          <div style={{ fontSize: 14, fontWeight: 700, color: nvInk(passed ? C.ok : C.ng, passed ? "#E4F6EC" : "#FBE9E7", 3) }}>{passed ? t.reachedPass : t.needMore(PASS - rate)}</div>
          <div style={{ fontSize: 12, color: "#6b5d52", marginTop: 4 }}>{t.correctOf(c, qs.length)}</div>
        </div>
        <Card title={t.wrongTitle(wrong.length)}>
          {wrong.length === 0 ? (
            <div style={{ fontSize: 13, color: C.ok }}>{t.allCorrect}</div>
          ) : wrong.map((w, idx) => (
            <div key={idx} style={{ padding: "8px 0", borderBottom: `1px solid ${C.light}`, fontSize: 13 }}>
              <div style={{ fontWeight: 600, marginBottom: 4 }}>
                <span style={{ background: DOM_HUE[w.Q.d], color: nvInk("#ffffff", DOM_HUE[w.Q.d]), borderRadius: 4, padding: "1px 6px", fontSize: 10.5, marginRight: 6 }}>{w.Q.d}</span>{qText(w.Q, lang)}
              </div>
              <div style={{ color: nvInk(C.ng, "#ffffff"), fontSize: 12.5 }}>{t.yourAnswer}：{w.pick.length ? w.pick.map(x => "ABCD"[x]).join(", ") : "—"}</div>
              <div style={{ color: nvInk(C.ok, "#ffffff"), fontSize: 12.5 }}>{t.answer}：{w.correctAns.map(x => "ABCD"[x]).join(", ")} {w.correctAns.map(x => qOpts(w.Q, lang)[x]).join(" / ")}</div>
              <div style={{ color: "#6b5d52", fontSize: 12.5, marginTop: 2 }}>{qExpl(w.Q, lang)}</div>
            </div>
          ))}
        </Card>
        <div style={{ display: "flex", gap: 10 }}>
          <button onClick={restart} style={{ flex: 1, padding: 13, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.retrySet}</button>
          <button onClick={() => setPhase("select")} style={{ flex: 1, padding: 13, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.toSetSelect}</button>
        </div>
      </div>
    );
  }

  const Q = qs[pos];
  const multi = !!Q.multi;
  const numNeeded = Array.isArray(Q.a) ? Q.a.length : 1;
  const pick = picks[pos] || [];
  const correctAns = Array.isArray(Q.a) ? Q.a : [Q.a];
  const isRevealed = isPractice && revealed[pos];
  const isLastQ = pos + 1 >= qs.length;
  const answeredCount = Object.keys(picks).filter(k => (picks[k] || []).length > 0).length;
  const timeWarn = !isPractice && timeLeft <= 180;

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10, background: timeWarn ? "#FBEAE8" : C.deep, color: timeWarn ? C.ng : nvInk("#ffffff", C.deep), borderRadius: 9, padding: "9px 14px" }}>
        <span style={{ fontSize: 13, fontWeight: 600 }}>
          {title} · {t.questionNo(pos + 1, qs.length)}
          <span style={{ marginLeft: 8, fontSize: 11 }}>{isPractice ? t.examModePractice : t.examModeReal}</span>
        </span>
        {isPractice
          ? <span style={{ fontSize: 13, fontWeight: 700 }}>{en ? "Answered" : "回答済"} {answeredCount}/{qs.length}</span>
          : <span style={{ fontSize: 17, fontWeight: 800 }}>{fmtTime(timeLeft)}</span>}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12, color: "#7b6d62", marginBottom: 6 }}>
        <span>{en ? "Answered" : "回答済"} {answeredCount}/{qs.length}</span>
        <button onClick={() => setFlags(f => ({ ...f, [pos]: !f[pos] }))}
          style={{ border: "none", background: "none", cursor: "pointer", fontSize: 12, fontWeight: 700, color: flags[pos] ? nvInk(C.primary, "#ffffff") : "#7b6d62" }}>
          {flags[pos] ? (en ? "★ Flagged" : "★ フラグ") : (en ? "☆ Flag" : "☆ フラグ")}
        </button>
      </div>
      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11, color: nvInk("#ffffff", DOM_HUE[Q.d]), background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>{Q.d} · {domName(Q.d, lang)}</div>
        {multi && <div style={{ display: "inline-block", marginLeft: 8, fontSize: 11, color: C.accent, fontWeight: 700, border: `1px solid ${C.accent}`, borderRadius: 4, padding: "2px 8px" }}>{t.multiSelect(numNeeded)}</div>}
        <div style={{ fontSize: 15, fontWeight: 600, margin: "12px 0 14px", lineHeight: 1.6 }}>{qText(Q, lang)}</div>
        {qOpts(Q, lang).map((opt, i) => {
          const on = pick.includes(i);
          let bg = on ? C.light : "#fff", bd = on ? C.primary : C.mid, col = C.ink, fw = on ? 700 : 500;
          let mark = on ? "✓" : "ABCD"[i], markBg = on ? C.primary : "#fff", markBd = on ? C.primary : C.mid;
          if (isRevealed) {
            const isCorrectOpt = correctAns.includes(i);
            if (isCorrectOpt) { bg = "#E8F5EE"; bd = C.ok; col = C.ok; fw = 700; markBg = C.ok; markBd = C.ok; mark = "✓"; }
            else if (on) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; fw = 700; markBg = C.ng; markBd = C.ng; mark = "✕"; }
            else { mark = "ABCD"[i]; markBg = "#fff"; markBd = C.mid; }
          }
          return (
            <button key={i} onClick={() => togglePick(pos, i, multi)} disabled={isRevealed}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9,
                border: `1.5px solid ${bd}`, background: bg, color: col, cursor: isRevealed ? "default" : "pointer", fontSize: 13.5, lineHeight: 1.45, fontWeight: fw }}>
              <span style={{ display: "inline-block", minWidth: 20, height: 20, lineHeight: "18px", textAlign: "center", marginRight: 8, borderRadius: multi ? 4 : 10, border: `2px solid ${markBd}`, background: markBg, color: markBg === "#fff" ? C.deep : "#fff", fontSize: 11, fontWeight: 700 }}>
                {mark}
              </span>{opt}
            </button>
          );
        })}
        {isRevealed && (
          <div style={{ marginTop: 12, background: C.light, borderRadius: 9, padding: 13, fontSize: 13.5, lineHeight: 1.55 }}>
            <strong style={{ color: nvInk(arrEq(pick, correctAns) ? C.ok : C.ng, C.light) }}>{arrEq(pick, correctAns) ? t.correct : t.incorrect}</strong>・{t.answerIs(correctAns.map(x => "ABCD"[x]).join(", "))}{qExpl(Q, lang)}
          </div>
        )}
      </div>

      {isPractice ? (
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <button onClick={() => setPos(p => Math.max(0, p - 1))} disabled={pos === 0}
            style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: pos === 0 ? nvInk("#bcae9f", "#ffffff", 3) : C.ink, fontWeight: 700, fontSize: 14, cursor: pos === 0 ? "default" : "pointer" }}>
            ← {en ? "Prev" : "前へ"}
          </button>
          {!isLastQ && (
            <button onClick={() => setPos(p => p + 1)}
              style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: nvInk(C.primary, "#ffffff"), fontWeight: 700, fontSize: 14, cursor: "pointer" }}>
              {en ? "Skip →" : "次へ →"}
            </button>
          )}
          {!isRevealed ? (
            <button onClick={() => revealPractice(pos)} disabled={pick.length === 0}
              style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: pick.length === 0 ? C.mid : C.accent, color: nvInk("#ffffff", pick.length === 0 ? C.mid : C.accent, 3), fontWeight: 700, fontSize: 14, cursor: pick.length === 0 ? "default" : "pointer" }}>
              {t.showAnswer}
            </button>
          ) : isLastQ ? (
            <button onClick={score} style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: C.ok, color: nvInk("#ffffff", C.ok, 3), fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.scoreBtn} ✓</button>
          ) : (
            <button onClick={() => setPos(p => p + 1)} style={{ flex: 2, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.checkContinue}</button>
          )}
        </div>
      ) : (
        <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
          <button onClick={() => setPos(p => Math.max(0, p - 1))} disabled={pos === 0}
            style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: pos === 0 ? nvInk("#bcae9f", "#ffffff", 3) : C.ink, fontWeight: 700, fontSize: 14, cursor: pos === 0 ? "default" : "pointer" }}>
            ← {en ? "Prev" : "前へ"}
          </button>
          {pos + 1 < qs.length ? (
            <button onClick={() => setPos(p => p + 1)} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: C.deep, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{en ? "Next" : "次へ"} →</button>
          ) : (
            <button onClick={score} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.ok, color: nvInk("#ffffff", C.ok, 3), fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.scoreBtn} ✓</button>
          )}
        </div>
      )}

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(34px, 1fr))", gap: 5, marginTop: 14 }}>
        {qs.map((_, i) => {
          const ans = (picks[i] || []).length > 0;
          const fl = flags[i];
          const cur = i === pos;
          const done = isPractice && revealed[i];
          return (
            <button key={i} onClick={() => setPos(i)}
              style={{ aspectRatio: "1", borderRadius: 6, cursor: "pointer", fontSize: 11, fontWeight: 700,
                border: cur ? `2px solid ${C.deep}` : `1px solid ${C.mid}`, background: fl ? "#FFE6B3" : done ? C.ok : ans ? C.primary : "#fff", color: (ans || done) && !fl ? (done ? "#fff" : C.deep) : C.ink }}>
              {i + 1}
            </button>
          );
        })}
      </div>
      {!isPractice && (
        <button onClick={score} style={{ width: "100%", marginTop: 12, padding: 12, borderRadius: 9, border: `1.5px solid ${C.ok}`, background: "#fff", color: C.ok, fontWeight: 700, fontSize: 14, cursor: "pointer" }}>{t.scoreBtn} ✓</button>
      )}
    </div>
  );
}

