// ===== 操作型：アーキテクチャビルダー =====
function ArchBuilder({ lang }) {
  const en = lang === "en";
  const tiers = [
    { id: "dns", label: "Route 53", hue: "#232F3E", req: [], why: en ? "Resolves your domain to the entry point and can do health-based failover." : "ドメインを入口へ解決し、ヘルスチェックによるフェイルオーバーも担う。" },
    { id: "cdn", label: "CloudFront + WAF", hue: "#146EB4", req: ["dns"], why: en ? "Edge caching plus L7 attack protection before traffic hits your app." : "エッジキャッシュと L7 攻撃防御をアプリ到達前に提供。" },
    { id: "lb", label: "ALB", hue: "#CC7000", req: ["cdn"], why: en ? "Distributes to healthy targets across AZs with L7 routing." : "複数 AZ の正常ターゲットへ L7 で振り分け。" },
    { id: "app", label: en ? "EC2 ASG (app)" : "EC2 ASG（アプリ）", hue: "#FF9900", req: ["lb"], why: en ? "Auto-scales the app tier across AZs for elasticity and HA." : "アプリ層を複数 AZ で自動スケールし弾力性と可用性を確保。" },
    { id: "db", label: en ? "RDS Multi-AZ" : "RDS マルチ AZ", hue: "#2E7D5B", req: ["app"], why: en ? "Database in private subnets with synchronous standby for failover." : "プライベートサブネットの DB＋同期スタンバイでフェイルオーバー。" },
  ];
  const [built, setBuilt] = useState([]);
  const [msg, setMsg] = useState("");
  const add = (tier) => {
    if (built.includes(tier.id)) return;
    const missing = tier.req.filter(r => !built.includes(r));
    if (missing.length) {
      const name = tiers.find(t => t.id === missing[0]).label;
      setMsg(en ? `Add ${name} first.` : `先に「${name}」を追加してください。`);
      return;
    }
    setBuilt([...built, tier.id]);
    setMsg(tier.why);
  };
  const reset = () => { setBuilt([]); setMsg(""); };
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 10 }}>{en ? "Tap tiers in order to assemble a highly available stack." : "上から順にタップして高可用スタックを組み立てよう。"}</div>
      <div style={{ minHeight: 30, marginBottom: 10 }}>
        {built.length === 0 ? <div style={{ fontSize: 12, color: nvInk("#bcae9f", "#ffffff"), textAlign: "center", padding: 12, border: `1.5px dashed ${C.mid}`, borderRadius: 10 }}>{en ? "(empty — start with Route 53)" : "（未構築 — Route 53 から）"}</div> :
          built.map((id, i) => {
            const tr = tiers.find(t => t.id === id);
            return <div key={id}>
              <div style={{ background: tr.hue, color: nvInk("#ffffff", tr.hue), borderRadius: 9, padding: "9px 13px", fontWeight: 700, fontSize: 13, textAlign: "center" }}>{tr.label}</div>
              {i < built.length - 1 && <div style={{ textAlign: "center", color: nvInk(C.mid, "#ffffff", 3), fontSize: 15 }}>↓</div>}
            </div>;
          })}
      </div>
      {msg && <div style={{ background: C.light, borderRadius: 9, padding: 11, fontSize: 12.5, color: C.deep, marginBottom: 10, lineHeight: 1.5 }}>{msg}</div>}
      <div style={{ display: "flex", flexWrap: "wrap", gap: 7, marginBottom: 10 }}>
        {tiers.map(tr => (
          <button key={tr.id} onClick={() => add(tr)} disabled={built.includes(tr.id)}
            style={{ padding: "8px 12px", borderRadius: 18, fontSize: 12.5, fontWeight: 700, cursor: built.includes(tr.id) ? "default" : "pointer",
              border: `1.5px solid ${tr.hue}`, background: built.includes(tr.id) ? C.light : "#fff", color: built.includes(tr.id) ? nvInk("#bcae9f", "#ffffff", 3) : nvInk(tr.hue, "#ffffff") }}>
            + {tr.label}
          </button>
        ))}
      </div>
      <button onClick={reset} style={{ width: "100%", padding: 10, borderRadius: 9, border: `1.5px solid ${C.mid}`, background: "#fff", color: C.ink, fontWeight: 700, fontSize: 13, cursor: "pointer" }}>{en ? "Reset" : "リセット"}</button>
      {built.length === tiers.length && <div style={{ marginTop: 10, background: "#E8F5EE", border: `2px solid ${C.ok}`, borderRadius: 10, padding: 12, fontSize: 13, color: C.ok, fontWeight: 700, textAlign: "center" }}>{en ? "✓ Complete: a classic HA 3-tier architecture!" : "✓ 完成：高可用な 3 層アーキテクチャ！"}</div>}
    </div>
  );
}

// ===== 操作型：料金シミュレーター =====
function CostSimulator({ lang }) {
  const en = lang === "en";
  const [hours, setHours] = useState(730);
  const od = 0.10; // 仮の単価 $/h
  const monthly = (rate) => Math.round(od * hours * rate * 100) / 100;
  const options = [
    [en ? "On-Demand" : "オンデマンド", 1.0, "#232F3E", en ? "No commitment" : "コミット不要"],
    [en ? "Savings Plans (1yr)" : "Savings Plans(1年)", 0.72, "#146EB4", en ? "~28% off" : "約28%引"],
    [en ? "Reserved (3yr)" : "リザーブド(3年)", 0.40, "#CC7000", en ? "~60% off" : "約60%引"],
    [en ? "Spot" : "スポット", 0.10, "#FF9900", en ? "~90% off, interruptible" : "約90%引・中断あり"],
  ];
  const pct = Math.round(hours / 730 * 100);
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 4 }}>{en ? "Monthly usage" : "月間の稼働"}: <strong>{hours}h</strong> ({pct}% {en ? "of the month" : "/月"})</div>
      <input type="range" min="1" max="730" value={hours} onChange={e => setHours(Number(e.target.value))} style={{ width: "100%", marginBottom: 12, accentColor: C.primary }} />
      {options.map(([name, rate, hue, note], i) => {
        const cost = monthly(rate);
        const max = monthly(1.0);
        return (
          <div key={i} style={{ marginBottom: 9 }}>
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
              <span style={{ fontWeight: 700, color: nvInk(hue, "#ffffff") }}>{name} <span style={{ color: "#7b6d62", fontWeight: 500, fontSize: 11 }}>{note}</span></span>
              <strong style={{ color: C.deep }}>${cost}</strong>
            </div>
            <div style={{ background: C.light, borderRadius: 6, height: 14, overflow: "hidden" }}>
              <div style={{ width: `${max ? (cost / max) * 100 : 0}%`, height: "100%", background: hue, transition: "width .2s" }} />
            </div>
          </div>
        );
      })}
      <div style={{ fontSize: 11.5, color: "#7b6d62", marginTop: 8, lineHeight: 1.5 }}>{en ? "Illustrative rates. Steady/long usage favors commitment; spiky/short favors On-Demand; interruptible favors Spot." : "※概算。常時稼働ほどコミットが有利、短期はオンデマンド、中断耐性があればスポットが有利。"}</div>
    </div>
  );
}

// ===== 操作型：DR シミュレーター =====
function DrSimulator({ lang }) {
  const en = lang === "en";
  const [rto, setRto] = useState(2); // 0..3
  const labels = [
    { name: en ? "Backup & Restore" : "バックアップ＆リストア", rto: en ? "Hours–day" : "数時間〜1日", cost: en ? "Lowest" : "最小", hue: "#FF9900", desc: en ? "Restore from backups on disaster. Cheapest, slowest." : "障害時にバックアップから復元。最安・最遅。" },
    { name: en ? "Pilot Light" : "パイロットライト", rto: en ? "~10s of min" : "数十分", cost: en ? "Low" : "低", hue: "#CC7000", desc: en ? "Core (DB) always on; spin up the rest on disaster." : "中核(DB)のみ常時稼働、有事に他を起動。" },
    { name: en ? "Warm Standby" : "ウォームスタンバイ", rto: en ? "Minutes" : "数分", cost: en ? "Medium" : "中", hue: "#146EB4", desc: en ? "Scaled-down full stack always running; scale up on failover." : "縮小版を常時稼働、切替時に増強。" },
    { name: en ? "Multi-Site" : "マルチサイト", rto: en ? "Near-zero" : "ほぼ0", cost: en ? "Highest" : "最大", hue: "#232F3E", desc: en ? "Active/active across regions; near-zero downtime." : "複数リージョンでアクティブ/アクティブ、ほぼ無停止。" },
  ];
  const cur = labels[rto];
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 6 }}>{en ? "Drag toward shorter RTO →" : "RTO を短くする方向へ →"}</div>
      <input type="range" min="0" max="3" step="1" value={rto} onChange={e => setRto(Number(e.target.value))} style={{ width: "100%", marginBottom: 4, accentColor: C.primary }} />
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10.5, color: "#7b6d62", marginBottom: 12 }}>
        <span>{en ? "cheap/slow" : "安い/遅い"}</span><span>{en ? "fast/costly" : "速い/高い"}</span>
      </div>
      <div style={{ background: cur.hue, color: nvInk("#ffffff", cur.hue), borderRadius: 11, padding: 16 }}>
        <div style={{ fontSize: 17, fontWeight: 800 }}>{cur.name}</div>
        <div style={{ display: "flex", gap: 14, margin: "8px 0", fontSize: 12.5 }}>
          <span>RTO: <strong>{cur.rto}</strong></span>
          <span>{en ? "Cost" : "コスト"}: <strong>{cur.cost}</strong></span>
        </div>
        <div style={{ fontSize: 12.5, lineHeight: 1.5 }}>{cur.desc}</div>
      </div>
    </div>
  );
}

// ===== 操作型：S3 クラス選定 =====
function S3Chooser({ lang }) {
  const en = lang === "en";
  const [freq, setFreq] = useState(2); // 0低..3高
  const [retr, setRetr] = useState(2); // 0即時必要..3遅くてよい
  let result, hue, why;
  if (freq >= 2) { result = "S3 Standard"; hue = "#232F3E"; why = en ? "Frequent access, no retrieval fee." : "高頻度アクセス・取り出し料なし。"; }
  else if (freq === 1) { result = "Standard-IA"; hue = "#146EB4"; why = en ? "Infrequent but instant access, retrieval fee, min 30d." : "低頻度だが即時・取り出し料あり・最低30日。"; }
  else { // freq 0
    if (retr === 0) { result = "Glacier Instant Retrieval"; hue = "#CC7000"; why = en ? "Archive but needs ms retrieval, min 90d." : "アーカイブだが即時取り出しが必要・最低90日。"; }
    else if (retr <= 2) { result = "Glacier Flexible Retrieval"; hue = "#E08E00"; why = en ? "Archive, minutes–hours retrieval." : "アーカイブ・数分〜数時間で取り出し。"; }
    else { result = "Glacier Deep Archive"; hue = "#FF9900"; why = en ? "Cheapest, ~12h retrieval, min 180d." : "最安・約12h・最低180日。"; }
  }
  const Slider = ({ label, val, set, lo, hi }) => (
    <div style={{ marginBottom: 12 }}>
      <div style={{ fontSize: 12.5, color: C.deep, fontWeight: 600, marginBottom: 4 }}>{label}</div>
      <input type="range" min="0" max="3" step="1" value={val} onChange={e => set(Number(e.target.value))} style={{ width: "100%", accentColor: C.primary }} />
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10.5, color: "#7b6d62" }}><span>{lo}</span><span>{hi}</span></div>
    </div>
  );
  return (
    <div>
      <Slider label={en ? "Access frequency" : "アクセス頻度"} val={freq} set={setFreq} lo={en ? "rare (archive)" : "稀(アーカイブ)"} hi={en ? "frequent" : "高頻度"} />
      {freq === 0 && <Slider label={en ? "Retrieval tolerance" : "取り出しの待てる度合い"} val={retr} set={setRetr} lo={en ? "need instant" : "即時必要"} hi={en ? "hours OK" : "数時間OK"} />}
      <div style={{ background: hue, color: nvInk("#ffffff", hue), borderRadius: 11, padding: 16, marginTop: 4 }}>
        <div style={{ fontSize: 11, fontWeight: 700 }}>{en ? "Recommended class" : "推奨クラス"}</div>
        <div style={{ fontSize: 18, fontWeight: 800, margin: "3px 0" }}>{result}</div>
        <div style={{ fontSize: 12.5, lineHeight: 1.5 }}>{why}</div>
      </div>
    </div>
  );
}

// ===== 操作型：Auto Scaling シミュレーター =====
function ScaleSimulator({ lang }) {
  const en = lang === "en";
  const [load, setLoad] = useState(40); // %
  const min = 2, max = 8, target = 50;
  const desired = Math.min(max, Math.max(min, Math.ceil((load / target) * min * (target / 100) * 4) || min));
  // よりシンプルに: 目標CPU50%を保つよう台数算出
  const calc = Math.max(min, Math.min(max, Math.round((load / target) * min)));
  const instances = Math.max(min, Math.min(max, Math.max(calc, Math.ceil(load / 25))));
  const perInstanceCpu = Math.min(100, Math.round(load * 2 / instances * (target / 50)));
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 4 }}>{en ? "Incoming load" : "流入負荷"}: <strong>{load}%</strong></div>
      <input type="range" min="0" max="100" value={load} onChange={e => setLoad(Number(e.target.value))} style={{ width: "100%", marginBottom: 14, accentColor: C.primary }} />
      <div style={{ display: "flex", gap: 6, justifyContent: "center", flexWrap: "wrap", marginBottom: 12 }}>
        {Array.from({ length: max }).map((_, i) => {
          const on = i < instances;
          return <div key={i} style={{ width: 38, height: 46, borderRadius: 8, border: `2px solid ${on ? C.primary : C.mid}`, background: on ? C.primary : "#fff", color: on ? nvInk(C.deep, C.primary) : nvInk("#bcae9f", "#ffffff", 3), display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, fontWeight: 800, transition: "all .2s" }}>{on ? "▣" : "·"}</div>;
        })}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
        <div style={{ background: C.light, borderRadius: 9, padding: 11, textAlign: "center" }}>
          <div style={{ fontSize: 11, color: "#6b5d52" }}>{en ? "Running instances" : "稼働台数"}</div>
          <div style={{ fontSize: 24, fontWeight: 800, color: C.deep }}>{instances}<span style={{ fontSize: 12, color: "#7b6d62" }}> / {max}</span></div>
        </div>
        <div style={{ background: C.light, borderRadius: 9, padding: 11, textAlign: "center" }}>
          <div style={{ fontSize: 11, color: "#6b5d52" }}>{en ? "Avg CPU/instance" : "1台あたりCPU"}</div>
          <div style={{ fontSize: 24, fontWeight: 800, color: perInstanceCpu > 80 ? C.ng : C.ok }}>{perInstanceCpu}%</div>
        </div>
      </div>
      <div style={{ fontSize: 12, color: "#6b5d52", lineHeight: 1.6 }}>{en ? `Target-tracking keeps CPU near ${target}%. As load rises, ASG adds instances (min ${min}, max ${max}) to hold the target.` : `ターゲット追跡は CPU を約 ${target}% に保つ。負荷が上がると ASG が台数を増やし（最小 ${min}・最大 ${max}）目標を維持。`}</div>
    </div>
  );
}

// ===== 操作型：IAM ポリシー評価器 =====
function IamEvaluator({ lang }) {
  const en = lang === "en";
  const [allow, setAllow] = useState(true);
  const [deny, setDeny] = useState(false);
  let result, hue, reason;
  if (deny) { result = en ? "DENIED" : "拒否"; hue = C.ng; reason = en ? "An explicit Deny always wins, overriding any Allow." : "明示的拒否は常に優先し、許可があっても覆る。"; }
  else if (allow) { result = en ? "ALLOWED" : "許可"; hue = C.ok; reason = en ? "Explicit Allow with no Deny → allowed." : "明示的許可があり拒否がない → 許可。"; }
  else { result = en ? "DENIED (implicit)" : "拒否（暗黙）"; hue = C.ng; reason = en ? "No explicit Allow → implicitly denied (least privilege)." : "明示的許可がない → 暗黙的に拒否（最小権限）。"; }
  const Toggle = ({ label, val, set, color }) => (
    <button onClick={() => set(!val)} style={{ flex: 1, padding: "12px 10px", borderRadius: 10, border: `2px solid ${val ? color : C.mid}`, background: val ? color : "#fff", color: val ? nvInk("#ffffff", color) : nvInk(C.ink, "#ffffff"), fontWeight: 700, fontSize: 13, cursor: "pointer" }}>
      {label}: {val ? "ON" : "OFF"}
    </button>
  );
  return (
    <div>
      <div style={{ fontSize: 12, color: "#6b5d52", marginBottom: 10 }}>{en ? "Toggle policy statements and see the evaluation result." : "ポリシーの有無を切り替えて評価結果を確認。"}</div>
      <div style={{ display: "flex", gap: 8, marginBottom: 12 }}>
        <Toggle label={en ? "Explicit Allow" : "明示的許可"} val={allow} set={setAllow} color={C.ok} />
        <Toggle label={en ? "Explicit Deny" : "明示的拒否"} val={deny} set={setDeny} color={C.ng} />
      </div>
      <div style={{ background: hue, color: nvInk("#ffffff", hue), borderRadius: 11, padding: 16, textAlign: "center" }}>
        <div style={{ fontSize: 11, fontWeight: 700 }}>{en ? "Result" : "評価結果"}</div>
        <div style={{ fontSize: 22, fontWeight: 800, margin: "3px 0" }}>{result}</div>
        <div style={{ fontSize: 12.5, lineHeight: 1.5 }}>{reason}</div>
      </div>
      <div style={{ fontSize: 11.5, color: "#7b6d62", marginTop: 8 }}>{en ? "Precedence: explicit Deny > explicit Allow > implicit Deny." : "優先順位：明示的拒否 ＞ 明示的許可 ＞ 暗黙的拒否。"}</div>
    </div>
  );
}

// CLF(クラウドプラクティショナー)の図でも同じAWS用語を引けるよう、用語集を外へ渡す。
App.GLOSSARY = GLOSSARY;
return App;
